const results = await Promise.allSettled([
  tools.exec_command({cmd:"command -v pdftotext; command -v pdfinfo; pdfinfo 'audits/Stylus Contracts Library v0.3.0 Audit.pdf' | head -20",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:2000}),
  tools.exec_command({cmd:"rg --files contracts examples extensions 2>/dev/null",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:6000}),
  tools.exec_command({cmd:"find audits -maxdepth 1 -type f -print",workdir:"/tmp/bench/ws",yield_time_ms:10000,max_output_tokens:1000})
]);
for (let i=0;i<results.length;i++) text(JSON.stringify({i,result:results[i]}));

