   215	            !v.iter().any(|v| v.z.is_zero()),
   216	            "projective Z coordinate should not be zero"
   217	        );
   218	
   219	        let mut z_s = v.iter().map(|g| g.z).collect::<Vec<_>>();
   220	
   221	        batch_inversion(&mut z_s);
