149	/// Ed25519 signing key which can be used to produce signatures.
150	///
151	/// Invariant: `verifying_key` is always the public key of
152	/// `secret_key`.
153	/// This prevents the signing function [oracle attack].
154	///
155	/// [oracle attack]: https://github.com/MystenLabs/ed25519-unsafe-libs
156	#[derive(Clone, PartialEq)]
157	pub struct SigningKey {
158	    /// The secret half of this signing key.
159	    pub(crate) signing_key: ExpandedSecretKey,
160	    /// The public half of this signing key.
161	    pub(crate) verifying_key: VerifyingKey,
162	}
163	
164	impl SigningKey {
165	    /// Get the [`VerifyingKey`] for this [`SigningKey`].
166	    #[must_use]
167	    pub fn verifying_key(&self) -> VerifyingKey {
168	        self.verifying_key
169	    }
170	
171	    /// Construct a [`SigningKey`] from a [`SecretKey`].
172	    #[inline]
173	    #[must_use]
174	    pub fn from_bytes(secret_key: &SecretKey) -> Self {
175	        let signing_key: ExpandedSecretKey = secret_key.into();
176	        let verifying_key: VerifyingKey = signing_key.clone().into();
177	        Self { signing_key, verifying_key }
178	    }
179	
180	    /// Verify a signature on a message with this signing key's public key.
181	    #[must_use]
182	    pub fn is_valid_signature(
183	        &self,
184	        message: &[u8],
185	        signature: &Signature,
186	    ) -> bool {
187	        self.verifying_key.is_valid(message, signature)
188	    }
189	
190	    /// Sign a message with this signing key's secret key.
191	    ///
192	    /// ```rust
193	    ///  use openzeppelin_crypto::eddsa::{SecretKey, SigningKey, SECRET_KEY_LENGTH};
194	    ///
195	    ///  let secret_key: SecretKey = [1u8; SECRET_KEY_LENGTH];
196	    ///  let signing_key = SigningKey::from_bytes(&secret_key);
197	    ///  let message = b"Sign me!";
198	    ///
199	    ///  let signature = signing_key.sign(message);
200	    ///  assert!(signing_key.is_valid_signature(message, &signature));
201	    /// ```
202	    #[must_use]
203	    pub fn sign(&self, message: &[u8]) -> Signature {
204	        let mut h = Sha512::new();
205	
206	        h.update(self.signing_key.hash_prefix);
207	        h.update(message);
208	
209	        let r = WideScalar::from_bigint(U512::from_bytes_le(
210	            h.finalize().as_slice(),
211	        ));
212	        let r = Scalar::from_fp(r);
213	
214	        let R = ProjectivePoint::generator() * r;
215	
216	        h = Sha512::new();
217	        h.update(CompressedPointY::from(R.into_affine()));
218	        h.update(CompressedPointY::from(
219	            self.verifying_key.point.into_affine(),
220	        ));
221	        h.update(message);
222	
223	        let k = WideScalar::from_bigint(U512::from_bytes_le(
224	            h.finalize().as_slice(),
225	        ));
226	        let k = Scalar::from_fp(k);
227	        let s: Scalar = (k * self.signing_key.scalar) + r;
228	
229	        Signature { R, s }
230	    }
231	}
