331	/// Ed25519 key for signature verification (public key).
332	#[derive(Copy, Clone, Default, PartialEq)]
333	pub struct VerifyingKey {
334	    /// Edwards point used for curve arithmetic operations.
335	    pub point: ProjectivePoint,
336	}
337	
338	impl VerifyingKey {
339	    /// Construct verifying key from affine point.
340	    #[must_use]
341	    pub fn from_affine(point: AffinePoint) -> Self {
342	        VerifyingKey { point: point.into() }
343	    }
344	
345	    /// Verify a signature on a message with this keypair's public key.
346	    #[must_use]
347	    pub fn is_valid(&self, message: &[u8], signature: &Signature) -> bool {
348	        let expected_r = self.compute_R(signature, message);
349	        expected_r == signature.R
350	    }
351	
352	    /// Helper for verification. Computes the expected `R` component of the
353	    /// signature. The caller compares this to the real `R` component.
354	    /// This computes `H(R || A || M)` where `H` is the 512-bit hash function
355	    /// given by `CtxDigest` (this is SHA-512 in spec-compliant Ed25519).
356	    fn compute_R(
357	        &self,
358	        signature: &Signature,
359	        message: &[u8],
360	    ) -> ProjectivePoint {
361	        let R = signature.R;
362	        let A = self.point;
363	
364	        let mut h = Sha512::new();
365	        h.update(CompressedPointY::from(R.into_affine()));
366	        h.update(CompressedPointY::from(A.into_affine()));
367	        h.update(message);
368	
369	        let k = WideScalar::from_bigint(U512::from_bytes_le(
370	            h.finalize().as_slice(),
371	        ));
372	        let k = Scalar::from_fp(k);
373	
374	        // Compute R: `-[k]A + [s]B = R`.
375	        A * (-k) + ProjectivePoint::generator() * signature.s
376	    }
377	
378	    /// Convert the [`VerifyingKey`] to a compressed byte representation.
379	    #[inline]
380	    #[must_use]
381	    pub fn to_bytes(&self) -> PublicKey {
382	        CompressedPointY::from(self.point.into_affine()).into()
383	    }
384	}
385	
386	impl From<ProjectivePoint> for VerifyingKey {
387	    fn from(point: ProjectivePoint) -> Self {
388	        VerifyingKey { point }
389	    }
390	}
391	
392	impl From<ExpandedSecretKey> for VerifyingKey {
393	    fn from(value: ExpandedSecretKey) -> Self {
394	        let point = ProjectivePoint::generator() * value.scalar;
395	        point.into()
396	    }
397	}
