233	/// In "Ed25519" format, the curve point `(x,y)` is
234	/// determined by the y-coordinate and the sign of `x`.
235	///
236	/// The first 255 bits of a `CompressedEdwardsY` represent the `y`-coordinate.
237	/// The high bit of the 32nd byte gives the sign of `x`.
238	#[derive(Copy, Clone, Hash)]
239	pub struct CompressedPointY([u8; 32]);
240	
241	impl AsRef<[u8]> for CompressedPointY {
242	    fn as_ref(&self) -> &[u8] {
243	        &self.0
244	    }
245	}
246	
247	impl From<CompressedPointY> for [u8; 32] {
248	    fn from(value: CompressedPointY) -> Self {
249	        value.0
250	    }
251	}
252	
253	const_assert!(
254	    <Curve25519Config as CurveConfig>::BaseField::HAS_MODULUS_SPARE_BIT
255	);
256	
257	impl From<AffinePoint> for CompressedPointY {
258	    fn from(point: AffinePoint) -> Self {
259	        let mut s: [u8; 32] = point
260	            .y
261	            .into_bigint()
262	            .into_bytes_le()
263	            .try_into()
264	            .expect("Y coordinate should be 32 bytes");
265	
266	        // Using the last bit to encode `x`, since the base field modulus is
267	        // asserted to have a spare bit.
268	        let is_odd = point.x.into_bigint().is_odd();
269	        s[31] ^= u8::from(is_odd) << 7;
270	
271	        CompressedPointY(s)
272	    }
273	}
