    15	pub(crate) fn interface_id(
    16	    _attr: &TokenStream,
    17	    input: TokenStream,
    18	) -> TokenStream {
    19	    let mut input = parse_macro_input!(input as ItemTrait);
    20	
    21	    let unsafety = input.unsafety;
    22	    let mut selectors_map =
    23	        HashMap::<String, (String, proc_macro2::TokenStream)>::new();
    24	
    25	    for item in &mut input.items {
    26	        let TraitItem::Fn(func) = item else {
    27	            continue;
    28	        };
    29	
    30	        let mut override_fn_name = None;
    31	        for attr in mem::take(&mut func.attrs) {
    32	            if attr.path().is_ident("selector") {
    33	                if override_fn_name.is_some() {
    34	                    error!(attr.path(), "more than one selector attribute");
    35	                }
    36	                let args: SelectorArgs = match attr.parse_args() {
    37	                    Ok(args) => args,
    38	                    Err(error) => error!(attr.path(), "{}", error),
    39	                };
    40	                override_fn_name = Some(args.name);
    41	            } else {
    42	                // Put back any other attributes.
    43	                func.attrs.push(attr);
    44	            }
    45	        }
    46	
    47	        let rust_fn_name = func.sig.ident.to_string();
    48	
    49	        let solidity_fn_name =
    50	            override_fn_name.unwrap_or(rust_fn_name.to_case(Case::Camel));
    51	
    52	        let arg_types = func.sig.inputs.iter().filter_map(|arg| match arg {
    53	            FnArg::Typed(t) => Some(t.ty.clone()),
    54	            // Opt out any `self` arguments.
    55	            FnArg::Receiver(_) => None,
    56	        });
    57	
    58	        // Build the function signature string for selector computation.
    59	        let type_strings: Vec<String> =
    60	            arg_types.clone().map(|ty| quote!(#ty).to_string()).collect();
    61	        let signature =
    62	            format!("{}({})", solidity_fn_name, type_strings.join(","));
    63	
    64	        let selector = quote! { alloy_primitives::aliases::B32::new(stylus_sdk::function_selector!(#solidity_fn_name #(, #arg_types )*)) };
