 20	    prelude::*,
 21	    storage::{StorageMap, StorageU256},
 22	};
 23	const ONE: U256 = uint!(0x1_U256);
 24	const HEX_FF: U256 = uint!(0xff_U256);
 25	
 26	/// State of a [`BitMap`] contract.
 27	#[storage]
 28	pub struct BitMap {
 29	    /// Inner laying mapping.
 30	    pub(crate) data: StorageMap<U256, StorageU256>,
 31	}
 32	
 33	impl BitMap {
 34	    /// Returns whether the bit at `index` is set.
 35	    ///
 36	    /// # Arguments
 37	    ///
 38	    /// * `index` - index of the boolean value in the bit map.
 39	    #[must_use]
 40	    pub fn get(&self, index: U256) -> bool {
 41	        let bucket = Self::get_bucket(index);
 42	        let mask = Self::get_mask(index);
 43	        let value = self.data.get(bucket);
 44	        (value & mask) != U256::ZERO
 45	    }
 46	
 47	    /// Sets the bit at `index` to the boolean `value`.
 48	    ///
 49	    /// # Arguments
 50	    ///
 51	    /// * `index` - index of boolean value in the bit map.
 52	    /// * `value` - boolean value to set in the bit map.
 53	    pub fn set_to(&mut self, index: U256, value: bool) {
 54	        if value {
 55	            self.set(index);
 56	        } else {
 57	            self.unset(index);
 58	        }
 59	    }
 60	
 61	    /// Sets the bit at `index`.
 62	    ///
 63	    /// # Arguments
 64	    ///
 65	    /// * `index` - index of boolean value that should be set `true`.
 66	    pub fn set(&mut self, index: U256) {
 67	        let bucket = Self::get_bucket(index);
 68	        let mask = Self::get_mask(index);
 69	        let mut value = self.data.setter(bucket);
 70	        let prev = value.get();
 71	        value.set(prev | mask);
 72	    }
 73	
 74	    /// Unsets the bit at `index`.
 75	    ///
 76	    /// # Arguments
 77	    ///
 78	    /// * `index` - index of boolean value that should be set `false`.
 79	    pub fn unset(&mut self, index: U256) {
 80	        let bucket = Self::get_bucket(index);
 81	        let mask = Self::get_mask(index);
 82	        let mut value = self.data.setter(bucket);
 83	        let prev = value.get();
 84	        value.set(prev & !mask);
 85	    }
 86	
 87	    /// Get mask of value in the bucket.
 88	    fn get_mask(index: U256) -> U256 {
 89	        ONE << (index & HEX_FF)
 90	    }
 91	
 92	    /// Get bucket index.
 93	    fn get_bucket(index: U256) -> U256 {
 94	        index >> 8
 95	    }
 96	}
