 21	/// State of an [`EnumerableSet`] contract.
 22	#[storage]
 23	pub struct EnumerableSet<T: Element> {
 24	    /// Values in the set.
 25	    values: StorageVec<T::StorageElement>,
 26	    /// Position is the index of the value in the `values` array plus 1.
 27	    /// Position 0 is used to mean a value is not in the set.
 28	    positions: StorageMap<T, StorageU256>,
 29	}
 30	
 31	impl<T: Element> EnumerableSet<T> {
 32	    /// Adds a value to a set.
 33	    ///
 34	    /// Returns true if the `value` was added to the set, that is if it was not
 35	    /// already present.
 36	    ///
 37	    /// # Arguments
 38	    ///
 39	    /// * `&mut self` - Write access to the set's state.
 40	    /// * `value` - The value to add to the set.
 41	    pub fn add(&mut self, value: T) -> bool {
 42	        if self.contains(value) {
 43	            false
 44	        } else {
 45	            self.values.push(value);
 46	
 47	            let position = self.length();
 48	            self.positions.setter(value).set(position);
 49	            true
 50	        }
 51	    }
 52	
 53	    /// Removes a `value` from a set.
 54	    ///
 55	    /// Returns true if the `value` was removed from the set, that is if it was
 56	    /// present.
 57	    ///
 58	    /// # Arguments
 59	    ///
 60	    /// * `&mut self` - Write access to the set's state.
 61	    /// * `value` - The value to remove from the set.
 62	    #[allow(clippy::missing_panics_doc)]
 63	    pub fn remove(&mut self, value: T) -> bool {
 64	        let position = self.positions.get(value);
 65	
 66	        if position.is_zero() {
 67	            false
 68	        } else {
 69	            let value_index = position - U256::ONE;
 70	            let last_index = self.length() - U256::ONE;
 71	
 72	            if value_index != last_index {
 73	                let last_value = self
 74	                    .values
 75	                    .get(last_index)
 76	                    .expect("element at `last_index` must exist");
 77	
 78	                self.values
 79	                    .setter(value_index)
 80	                    .expect(
 81	                        "element at `value_index` must exist - is being removed",
 82	                    )
 83	                    .set(last_value);
 84	
 85	                self.positions.setter(last_value).set(position);
 86	            }
 87	
 88	            self.values.pop();
 89	
 90	            self.positions.delete(value);
 91	
 92	            true
 93	        }
 94	    }
 95	
 96	    /// Remove all values from a set.
 97	    ///
 98	    /// # WARNING
 99	    ///
100	    /// This function has an unbounded cost that scales with set size.
101	    /// Developers should keep in mind that using it may render the function
102	    /// uncallable if the set grows to the point where clearing it consumes too
103	    /// much gas to fit in a block.
104	    ///
105	    /// # Arguments
106	    ///
107	    /// * `&mut self` - Write access to the set's state.
108	    #[allow(clippy::missing_panics_doc)]
109	    pub fn clear(&mut self) {
110	        for idx in 0..self.values.len() {
111	            let v = self
112	                .values
113	                .get(idx)
114	                .expect("element at index: {idx} must exist");
115	            self.positions.delete(v);
116	        }
117	
118	        self.values.erase();
119	    }
120	
121	    /// Returns true if the `value` is in the set.
122	    ///
123	    /// # Arguments
124	    ///
125	    /// * `&self` - Read access to the set's state.
126	    /// * `value` - The value to check for in the set.
127	    #[must_use]
128	    pub fn contains(&self, value: T) -> bool {
129	        !self.positions.get(value).is_zero()
130	    }
131	
132	    /// Returns the number of values in the set.
133	    ///
134	    /// Note this implementation's maximum length will technically be `usize`
135	    /// because that is the type returned by the underlying
136	    /// [`StorageVec::len`].
137	    ///
138	    /// # Arguments
139	    ///
140	    /// * `&self` - Read access to the set's state.
141	    #[must_use]
142	    pub fn length(&self) -> U256 {
143	        U256::from(self.values.len())
144	    }
145	
146	    /// Returns the value stored at position `index` in the set.
147	    ///
148	    /// Note that there are no guarantees on the ordering of values inside the
149	    /// array, and it may change when more values are added or removed.
150	    ///
151	    /// # Arguments
152	    ///
153	    /// * `&self` - Read access to the set's state.
154	    /// * `index` - The index of the value to return.
155	    #[must_use]
156	    pub fn at(&self, index: U256) -> Option<T> {
157	        self.values.get(index)
158	    }
159	
160	    /// Returns the entire set in an array.
161	    ///
162	    /// # WARNING
163	    ///
164	    /// This operation will copy the entire storage to memory, which can be
165	    /// quite expensive. This is designed to mostly be used by view
166	    /// accessors that are queried without any gas fees. Developers should keep
167	    /// in mind that this function has an unbounded cost, and using it as
168	    /// part of a state-changing function may render the function uncallable
169	    /// if the set grows to a point where copying to memory consumes too much
170	    /// gas to fit in a block.
171	    ///
172	    /// # Arguments
173	    ///
174	    /// * `&self` - Read access to the set's state.
175	    #[allow(clippy::missing_panics_doc)]
176	    #[must_use]
177	    pub fn values(&self) -> Vec<T> {
178	        let mut values = Vec::new();
179	        for idx in 0..self.values.len() {
180	            values.push(
181	                self.values
182	                    .get(idx)
183	                    .expect("element at index: {idx} must exist"),
184	            );
185	        }
186	        values
187	    }
