189	    /// Returns a slice of the set in an array.
190	    ///
191	    /// This function allows querying subsets of large sets to avoid
192	    /// out-of-gas scenarios when the full set would be too expensive
193	    /// to return in a single call.
194	    ///
195	    /// # WARNING
196	    ///
197	    /// This operation will copy the entire storage to memory, which can be
198	    /// quite expensive. This is designed to mostly be used by view
199	    /// accessors that are queried without any gas fees. Developers should keep
200	    /// in mind that this function has an unbounded cost, and using it as
201	    /// part of a state-changing function may render the function uncallable
202	    /// if the set grows to a point where copying to memory consumes too much
203	    /// gas to fit in a block.
204	    ///
205	    /// # Arguments
206	    ///
207	    /// * `&self` - Read access to the set's state.
208	    /// * `start` - The starting index (inclusive).
209	    /// * `end` - The ending index (exclusive).
210	    #[allow(clippy::missing_panics_doc)]
211	    #[must_use]
212	    pub fn values_slice(&self, start: U256, end: U256) -> Vec<T> {
213	        let len = self.length();
214	
215	        // clamp parameters to valid ranges as in Solidity implementation: <https://github.com/OpenZeppelin/openzeppelin-contracts/blob/448538259f1feeb24f3e3201115d70818ba876cb/contracts/utils/structs/EnumerableSet.sol#L189>.
216	        let end = core::cmp::min(end, len);
217	        let start = core::cmp::min(start, end);
218	
219	        // Uses optimized native iteration for typical cases where indices
220	        // fit within [`usize`] bounds. Falls back to [`U256`] arithmetic for
221	        // extremely large indices (theoretical edge case).
222	        if let (Ok(start_idx), Ok(end_idx)) =
223	            (usize::try_from(start), usize::try_from(end))
224	        {
225	            // fast path: use native [`usize`] iteration with iterator
226	            // chains.
227	            (start_idx..end_idx)
228	                .map(|idx| {
229	                    self.at(U256::from(idx))
230	                        .expect("element at index: {idx} must exist")
231	                })
232	                .collect()
233	        } else {
234	            // slow path: pure [`U256`] arithmetic for extremely large indices.
235	            let mut result = Vec::new();
236	            let mut current = start;
237	
238	            while current < end {
239	                let value = self
240	                    .at(current)
241	                    .expect("element at index: {current} must exist");
242	                result.push(value);
243	
244	                current += U256::ONE;
245	            }
246	
247	            result
248	        }
249	    }
250	}
