 94	        &self,
 95	    ) -> ([u8; 1], String, String, U256, Address, [u8; 32], Vec<U256>) {
 96	        (
 97	            FIELDS,
 98	            Self::NAME.to_owned(),
 99	            Self::VERSION.to_owned(),
100	            Self::chain_id(),
101	            Self::contract_address(),
102	            SALT,
103	            Vec::new(),
104	        )
105	    }
106	
107	    /// Returns the domain separator for the current chain.
108	    ///
109	    /// # Arguments
110	    ///
111	    /// * `&self` - Read access to the contract's state.
112	    fn domain_separator_v4(&self) -> B256 {
113	        let encoded = DomainSeparatorTuple::abi_encode(&(
114	            TYPE_HASH,
115	            Self::HASHED_NAME,
116	            Self::HASHED_VERSION,
117	            Self::chain_id(),
118	            Self::contract_address(),
119	        ));
120	
121	        keccak256(encoded)
122	    }
123	
124	    /// Given an already [hashed struct], this function returns the hash of the
125	    /// fully encoded EIP-712 message for this domain.
126	    ///
127	    /// [hashed struct]: https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct
128	    ///
129	    /// # Arguments
130	    ///
131	    /// * `&self` - Read access to the contract's state.
132	    fn hash_typed_data_v4(&self, struct_hash: B256) -> B256 {
133	        let domain_separator = self.domain_separator_v4();
134	        to_typed_data_hash(&domain_separator, &struct_hash)
135	    }
