  2	//!
  3	//! These functions can be used to verify that a message was signed
  4	//! by the holder of the private keys of a given address.
  5	use alloc::vec::Vec;
  6	
  7	use alloy_primitives::{address, uint, Address, B256, U256};
  8	use alloy_sol_types::SolType;
