 14	/// Address of the `ecRecover` EVM precompile.
 15	pub const ECRECOVER_ADDR: Address =
 16	    address!("0000000000000000000000000000000000000001");
 17	
 18	/// Upper range for `s` value from the signature.
 19	pub const SIGNATURE_S_UPPER_BOUND: U256 = uint!(
 20	    0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF5D576E7357A4501DDFE92F46681B20A0_U256
 21	);
 22	
