  1	//! [EIP-712](https://eips.ethereum.org/EIPS/eip-712) is a standard for hashing
  2	//! and signing typed structured data.
  3	//!
  4	//! The implementation of the domain separator was designed to be as efficient
  5	//! as possible while still properly updating the chain id to protect against
  6	//! replay attacks on an eventual fork of the chain.
  7	//!
  8	//! NOTE: This contract implements the version of the encoding known as "v4", as
  9	//! implemented by the JSON RPC method [`eth_signTypedDataV4`] in `MetaMask`.
 10	//!
 11	//! [`eth_signTypedDataV4`]: https://docs.metamask.io/guide/signing-data.html
 12	
 13	use alloc::{borrow::ToOwned, string::String, vec::Vec};
 14	
 15	use alloy_primitives::{keccak256, Address, B256, U256};
 16	use alloy_sol_types::{sol, SolType};
 17	use stylus_sdk::{block, contract};
 18	
 19	/// Keccak-256 hash of the EIP-712 domain separator type string.
 20	const TYPE_HASH: [u8; 32] =
 21	    keccak_const::Keccak256::new()
 22	        .update(b"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)")
 23	        .finalize();
 24	
 25	/// Field for the domain separator.
 26	const FIELDS: [u8; 1] = [0x0f];
 27	
 28	/// Salt for the domain separator.
 29	const SALT: [u8; 32] = [0u8; 32];
 30	
 31	/// Prefix for ERC-191 version with `0x01`.
 32	const TYPED_DATA_PREFIX: [u8; 2] = [0x19, 0x01];
 33	
 34	/// Tuple for the domain separator.
 35	type DomainSeparatorTuple = sol! {
 36	    tuple(bytes32, bytes32, bytes32, uint256, address)
 37	};
 38	
 39	/// Returns the keccak256 digest of an EIP-712 typed data (ERC-191 version
 40	/// `0x01`).
 41	///
 42	/// The digest is calculated from a `domain_separator` and a `struct_hash`, by
 43	/// prefixing them with `[TYPED_DATA_PREFIX]` and hashing the result. It
 44	/// corresponds to the hash signed by the [eth_signTypedData] JSON-RPC method as
 45	/// part of EIP-712.
 46	///
 47	/// [eth_signTypedData]: https://eips.ethereum.org/EIPS/eip-712
 48	#[must_use]
 49	pub fn to_typed_data_hash(
 50	    domain_separator: &[u8; 32],
 51	    struct_hash: &[u8; 32],
 52	) -> B256 {
 53	    let mut preimage = [0u8; 66];
 54	    preimage[..2].copy_from_slice(&TYPED_DATA_PREFIX);
 55	    preimage[2..34].copy_from_slice(domain_separator);
 56	    preimage[34..].copy_from_slice(struct_hash);
 57	    keccak256(preimage)
 58	}
 59	
 60	/// EIP-712 Contract interface.
 61	pub trait IEip712 {
 62	    /// Immutable name of EIP-712 instance.
 63	    const NAME: &'static str;
 64	    /// Hashed name of EIP-712 instance.
 65	    const HASHED_NAME: [u8; 32] =
 66	        keccak_const::Keccak256::new().update(Self::NAME.as_bytes()).finalize();
 67	
 68	    /// Immutable version of EIP-712 instance.
 69	    const VERSION: &'static str;
 70	    /// Hashed version of EIP-712 instance.
 71	    const HASHED_VERSION: [u8; 32] = keccak_const::Keccak256::new()
 72	        .update(Self::VERSION.as_bytes())
 73	        .finalize();
 74	
 75	    /// Returns chain id.
 76	    #[must_use]
 77	    fn chain_id() -> U256 {
 78	        U256::from(block::chainid())
 79	    }
 80	
 81	    /// Returns the contract's address.
 82	    #[must_use]
 83	    fn contract_address() -> Address {
 84	        contract::address()
 85	    }
 86	
 87	    /// Returns the fields and values that describe the domain separator used by
 88	    /// this contract for EIP-712 signature.
 89	    ///
 90	    /// # Arguments
 91	    ///
 92	    /// * `&self` - Read access to the contract's state.
 93	    fn eip712_domain(
 94	        &self,
 95	    ) -> ([u8; 1], String, String, U256, Address, [u8; 32], Vec<U256>) {
 96	        (
 97	            FIELDS,
 98	            Self::NAME.to_owned(),
 99	            Self::VERSION.to_owned(),
100	            Self::chain_id(),
101	            Self::contract_address(),
102	            SALT,
103	            Vec::new(),
104	        )
105	    }
106	
107	    /// Returns the domain separator for the current chain.
108	    ///
109	    /// # Arguments
110	    ///
111	    /// * `&self` - Read access to the contract's state.
112	    fn domain_separator_v4(&self) -> B256 {
113	        let encoded = DomainSeparatorTuple::abi_encode(&(
114	            TYPE_HASH,
115	            Self::HASHED_NAME,
116	            Self::HASHED_VERSION,
117	            Self::chain_id(),
118	            Self::contract_address(),
119	        ));
120	
121	        keccak256(encoded)
122	    }
123	
124	    /// Given an already [hashed struct], this function returns the hash of the
125	    /// fully encoded EIP-712 message for this domain.
126	    ///
127	    /// [hashed struct]: https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct
128	    ///
129	    /// # Arguments
130	    ///
131	    /// * `&self` - Read access to the contract's state.
132	    fn hash_typed_data_v4(&self, struct_hash: B256) -> B256 {
133	        let domain_separator = self.domain_separator_v4();
134	        to_typed_data_hash(&domain_separator, &struct_hash)
135	    }
136	}
