 74	impl Nonces {
 75	    /// Consumes a nonce for the given `account`.
 76	    ///
 77	    /// # Arguments
 78	    ///
 79	    /// * `&mut self` - Write access to the contract's state.
 80	    /// * `owner` - The address for which to consume the nonce.
 81	    ///
 82	    /// # Panics
 83	    ///
 84	    /// * If the nonce for the given `owner` exceeds [`U256::MAX`].
 85	    pub fn use_nonce(&mut self, owner: Address) -> U256 {
 86	        let nonce = self.nonces.get(owner);
 87	
 88	        self.nonces
 89	            .setter(owner)
 90	            .add_assign_checked(ONE, "nonce should not exceed `U256::MAX`");
 91	
 92	        nonce
 93	    }
 94	
 95	    /// Same as `use_nonce` but checking that the `nonce` is the next valid for
 96	    /// the owner.
 97	    ///
 98	    /// # Arguments
 99	    ///
100	    /// * `&mut self` - Write access to the contract's state.
101	    /// * `owner` - The address for which to consume the nonce.
102	    /// * `nonce` - The nonce to consume.
103	    ///
104	    /// # Errors
105	    ///
106	    /// * [`Error::InvalidAccountNonce`] - Returns an error if the `nonce` is
107	    ///   not the next valid nonce for the owner.
108	    ///
109	    /// # Panics
110	    ///
111	    /// * If the nonce for the given `owner` exceeds [`U256::MAX`].
112	    pub fn use_checked_nonce(
113	        &mut self,
114	        owner: Address,
115	        nonce: U256,
116	    ) -> Result<(), Error> {
117	        let current_nonce = self.use_nonce(owner);
118	
119	        if nonce != current_nonce {
120	            return Err(Error::InvalidAccountNonce(InvalidAccountNonce {
121	                account: owner,
122	                current_nonce,
123	            }));
124	        }
125	
126	        Ok(())
127	    }
128	}
