 18	
 19	    sol! {
 20	        /// Indicates an error related to the operation that failed
 21	        /// because `total_supply` exceeded the `cap`.
 22	        #[derive(Debug)]
 23	        #[allow(missing_docs)]
 24	        error ERC20ExceededCap(uint256 increased_supply, uint256 cap);
 25	
 26	        /// Indicates an error related to the operation that failed
 27	        /// because the supplied `cap` is not a valid cap value.
 28	        #[derive(Debug)]
 29	        #[allow(missing_docs)]
 30	        error ERC20InvalidCap(uint256 cap);
 31	    }
 32	}
 33	
 34	/// A Capped error.
 35	#[derive(SolidityError, Debug)]
 36	pub enum Error {
 37	    /// Indicates an error related to the operation that failed
 38	    /// because `total_supply` exceeded the `cap`.
 39	    ExceededCap(ERC20ExceededCap),
 40	    /// Indicates an error related to the operation that failed
 41	    /// because the supplied `cap` is not a valid cap value.
 42	    InvalidCap(ERC20InvalidCap),
 43	}
