 51	/// State of a [`Capped`] Contract.
 52	#[storage]
 53	pub struct Capped {
 54	    /// A cap to the supply of tokens.
 55	    pub(crate) cap: StorageU256,
 56	}
 57	
 58	/// Interface for the token supply cap logic.
 59	#[interface_id]
 60	pub trait ICapped {
 61	    /// Returns the cap on the token's total supply.
 62	    #[must_use]
 63	    fn cap(&self) -> U256;
 64	}
 65	
 66	#[public]
 67	#[implements(ICapped)]
 68	impl Capped {
 69	    /// Constructor.
 70	    ///
 71	    /// # Arguments
 72	    ///
 73	    /// * `&mut self` - Write access to the contract's state.
 74	    /// * `cap` - The token supply cap.
 75	    ///
 76	    /// # Errors
 77	    ///
 78	    /// * [`Error::InvalidCap`] - If cap is [`U256::ZERO`].
 79	    #[constructor]
 80	    pub fn constructor(&mut self, cap: U256) -> Result<(), Error> {
 81	        if cap.is_zero() {
 82	            return Err(Error::InvalidCap(ERC20InvalidCap { cap }));
 83	        }
