//! ([Homogeneous coordinates]).
//!
//! [Homogeneous coordinates]: https://en.wikipedia.org/wiki/Homogeneous_coordinates
use alloc::vec::Vec;
use core::{
    borrow::Borrow,
    fmt::{Display, Formatter},
    hash::{Hash, Hasher},
    ops::{Add, AddAssign, Mul, MulAssign, Neg, Sub, SubAssign},
