//! This module contains Pedersen Hash Function implementation.
///
/// Based on the [Starknet] implementation of the Pedersen Hash Function.
///
/// [Starknet]: <https://github.com/starkware-libs/cairo-lang/blob/master/src/starkware/crypto/signature/fast_pedersen_hash.py>
pub mod instance;
pub mod params;

use crate::{
    curve::{AffineRepr, CurveConfig},
    field::prime::PrimeField,
    pedersen::params::PedersenParams,
};

/// Pedersen hash.
#[derive(Clone, Debug)]
pub struct Pedersen<F: PedersenParams<P>, P: CurveConfig>
where
    <P as CurveConfig>::BaseField: PrimeField,
    F::AffineRepr: AffineRepr<
        Config = P,
        BaseField = P::BaseField,
        ScalarField = P::ScalarField,
    >,
{
    params: core::marker::PhantomData<F>,
    curve: core::marker::PhantomData<P>,
}

impl<F: PedersenParams<P>, P: CurveConfig> Default for Pedersen<F, P>
where
    <P as CurveConfig>::BaseField: PrimeField,
    F::AffineRepr: AffineRepr<
        Config = P,
        BaseField = P::BaseField,
        ScalarField = P::ScalarField,
    >,
{
    fn default() -> Self {
        Self::new()
    }
}

impl<F: PedersenParams<P>, P: CurveConfig> Pedersen<F, P>
where
    <P as CurveConfig>::BaseField: PrimeField,
    F::AffineRepr: AffineRepr<
        Config = P,
        BaseField = P::BaseField,
        ScalarField = P::ScalarField,
    >,
{
    #[must_use]
    #[inline]
    /// Creates a new Pedersen hash instance.
    pub fn new() -> Self {
        Self {
            params: core::marker::PhantomData,
            curve: core::marker::PhantomData,
        }
    }

    fn process_single_element(
        element: P::BaseField,
        p1: F::AffineRepr,
        p2: F::AffineRepr,
    ) -> <F::AffineRepr as AffineRepr>::Group {
        let element = element.into_bigint();

        let high_nibble = element >> F::LOW_PART_BITS;
        let low_part = element & F::LOW_PART_MASK;

        p1.mul_bigint(low_part) + p2.mul_bigint(high_nibble)
    }

    /// Computes the Starkware version of the Pedersen hash of x and y.
    ///
    /// The hash is defined by:
    /// [`PedersenParams::P_0`] + `x_low` * [`PedersenParams::P_1`] +
    /// `x_high` * [`PedersenParams::P_2`] + `y_low` * [`PedersenParams::P_3`] +
    /// `y_high` * [`PedersenParams::P_4`]
    ///
    /// where `x_low` is the 248 low bits of `x`, `x_high` is the 4 high bits of
    /// `x` and similarly for `y`. [`PedersenParams::P_0`],
    /// [`PedersenParams::P_1`], [`PedersenParams::P_2`],
    /// [`PedersenParams::P_3`], [`PedersenParams::P_4`] are constant points
    /// generated from the digits of pi.
    ///
    /// # Arguments
    ///
    /// * `&self` - Pedersen hasher instance.
    /// * `x` - The x coordinate of the point to hash.
    /// * `y` - The y coordinate of the point to hash.
    #[must_use]
    pub fn hash<T>(&self, x: T, y: T) -> Option<P::BaseField>
    where
        T: Into<P::BaseField>,
    {
        let hash: <F::AffineRepr as AffineRepr>::Group = F::P_0.into_group()
            + Self::process_single_element(x.into(), F::P_1, F::P_2)
            + Self::process_single_element(y.into(), F::P_3, F::P_4);

        let hash: F::AffineRepr = hash.into();
        hash.x()
    }
}
//! Pedersen hash parameters.

use crate::{curve::CurveConfig, field::prime::PrimeField};

/// Pedersen hash parameters.
pub trait PedersenParams<P: CurveConfig>
where
    <P as CurveConfig>::BaseField: PrimeField,
{
    /// The affine representation type for this Elliptic Curve.
    type AffineRepr;

    /// Number of elements in the hash.
    const N_ELEMENT_BITS_HASH: usize;

    /// Shift point.
    const P_0: Self::AffineRepr;

    /// Constant point -- `P_1`.
    const P_1: Self::AffineRepr;
    /// Constant point -- `P_2`.
    const P_2: Self::AffineRepr;
    /// Constant point -- `P_3`.
    const P_3: Self::AffineRepr;
    /// Constant point -- `P_4`.
    const P_4: Self::AffineRepr;

    /// Low bits of a value to hash.
    const LOW_PART_BITS: u32;
    /// Low part mask for a value to hash.
    const LOW_PART_MASK: <P::BaseField as PrimeField>::BigInt;
}
//! Generic hashing support.
//!
//! This module provides a generic way to compute the [hash] of a value. It is
//! intended to be used as a replacement for [`core::hash`], which we can't use
//! because [`core::hash::Hasher::finish`] returns a `u64`.
//!
//! [hash]: https://en.wikipedia.org/wiki/Hash_function

/// A hashable type.
///
/// Types implementing `Hash` are able to be [`Hash::hash`]ed with an instance
/// of [`Hasher`].
pub trait Hash {
    /// Feeds this value into the given [`Hasher`].
    fn hash<H: Hasher>(&self, state: &mut H);
}

/// A trait for hashing an arbitrary stream of bytes.
///
/// Instances of `Hasher` usually represent state that is changed while hashing
/// data.
///
/// `Hasher` provides a fairly basic interface for retrieving the generated hash
/// (with [`Hasher::finalize`]), and absorbing an arbitrary number of bytes
/// (with [`Hasher::update`]). Most of the time, [`Hasher`] instances are used
/// in conjunction with the [`Hash`] trait.
pub trait Hasher {
    /// The output type of this hasher.
    ///
    /// For [`core::hash`] types, it's `u64`. For [`tiny_keccak`], it's `[u8]`.
    /// For this crate, it's `[u8; 32]`.
    type Output;

    /// Absorb additional input. Can be called multiple times.
    fn update(&mut self, input: impl AsRef<[u8]>);

    /// Output the hashing algorithm state.
    fn finalize(self) -> Self::Output;
}

/// A trait for creating instances of [`Hasher`].
///
/// A `BuildHasher` is typically used (e.g., by [`HashMap`]) to create
/// [`Hasher`]s for each key such that they are hashed independently of one
/// another, since [`Hasher`]s contain state.
///
/// For each instance of `BuildHasher`, the [`Hasher`]s created by
/// [`build_hasher`] should be identical. That is, if the same stream of bytes
/// is fed into each hasher, the same output will also be generated.
///
/// # Examples
///
/// ```rust
/// use openzeppelin_crypto::KeccakBuilder;
/// use openzeppelin_crypto::hash::{BuildHasher, Hash, Hasher};
///
/// let b = KeccakBuilder;
/// let mut hasher_1 = b.build_hasher();
/// let mut hasher_2 = b.build_hasher();
///
/// hasher_1.update([1]);
/// hasher_2.update([1]);
///
/// assert_eq!(hasher_1.finalize(), hasher_2.finalize());
/// ```
///
/// [`build_hasher`]: BuildHasher::build_hasher
/// [`HashMap`]: ../../std/collections/struct.HashMap.html
pub trait BuildHasher {
    /// Type of the hasher that will be created.
    type Hasher: Hasher;

    /// Creates a new hasher.
    ///
    /// Each call to `build_hasher` on the same instance should produce
    /// identical [`Hasher`]s.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use openzeppelin_crypto::KeccakBuilder;
    /// use openzeppelin_crypto::hash::BuildHasher;
    ///
    /// let b = KeccakBuilder;
    /// let hasher = b.build_hasher();
    /// ```
    fn build_hasher(&self) -> Self::Hasher;

    /// Calculates the hash of a single value.
    ///
    /// This is intended as a convenience for code which *consumes* hashes, such
    /// as the implementation of a hash table or in unit tests that check
    /// whether a custom [`Hash`] implementation behaves as expected.
    ///
    /// This must not be used in any code which *creates* hashes, such as in an
    /// implementation of [`Hash`].  The way to create a combined hash of
    /// multiple values is to call [`Hash::hash`] multiple times using the same
    /// [`Hasher`], not to call this method repeatedly and combine the results.
    ///
    /// # Examples
    ///
    /// ```rust
    /// use openzeppelin_crypto::KeccakBuilder;
    /// use openzeppelin_crypto::hash::{BuildHasher, Hash};
    ///
    /// let b = KeccakBuilder;
    /// let hash_1 = b.hash_one([0u8; 32]);
    /// let hash_2 = b.hash_one([0u8; 32]);
    /// assert_eq!(hash_1, hash_2);
    ///
    /// let hash_1 = b.hash_one([1u8; 32]);
    /// assert_ne!(hash_1, hash_2);
    /// ```
    fn hash_one<Hashable>(
        &self,
        h: Hashable,
    ) -> <Self::Hasher as Hasher>::Output
    where
        Hashable: Hash,
        Self: Sized,
        Self::Hasher: Hasher,
    {
        let mut hasher = self.build_hasher();
        h.hash(&mut hasher);
        hasher.finalize()
    }
}

/// Hash the pair `(a, b)` with `state`.
///
/// Returns the finalized hash output from the hasher.
///
/// # Arguments
///
/// * `a` - The first value to hash.
/// * `b` - The second value to hash.
/// * `state` - The hasher state to use.
#[inline]
pub fn hash_pair<S, H>(a: &H, b: &H, mut state: S) -> S::Output
where
    H: Hash + ?Sized,
    S: Hasher,
{
    a.hash(&mut state);
    b.hash(&mut state);
    state.finalize()
}

/// Sort the pair `(a, b)` and hash the result with `state`. Frequently used
/// when working with merkle proofs.
#[inline]
pub fn commutative_hash_pair<S, H>(a: &H, b: &H, state: S) -> S::Output
where
    H: Hash + PartialOrd,
    S: Hasher,
{
    if a > b {
        hash_pair(b, a, state)
    } else {
        hash_pair(a, b, state)
    }
}

