 69	    /// Check [`IErc721Metadata::token_uri()`] for more details.
 70	    #[allow(clippy::missing_errors_doc)]
 71	    pub fn token_uri(
 72	        &self,
 73	        token_id: U256,
 74	        erc721: &impl IErc721<Error = erc721::Error>,
 75	        metadata: &Erc721Metadata,
 76	    ) -> Result<String, erc721::Error> {
 77	        erc721.owner_of(token_id)?;
 78	
 79	        let token_uri = self.token_uris.getter(token_id).get_string();
 80	        let base = metadata.base_uri();
 81	
 82	        // If there is no base URI, return the token URI.
 83	        if base.is_empty() {
 84	            return Ok(token_uri);
 85	        }
 86	
 87	        // If both are set, concatenate the `base_uri` and `token_uri`.
 88	        let uri = if token_uri.is_empty() {
 89	            metadata.token_uri(token_id, erc721)?
 90	        } else {
 91	            base + &token_uri
 92	        };
 93	
 94	        Ok(uri)
 95	    }
 96	}
