 25	pub(crate) fn interface_id(
 26	    _attr: &TokenStream,
 27	    input: TokenStream,
 28	) -> TokenStream {
 29	    let mut input = parse_macro_input!(input as ItemTrait);
 30	
 31	    let unsafety = input.unsafety;
 32	    let mut selectors = Vec::<MethodSelector>::new();
 33	    let has_trait_generics = !input.generics.params.is_empty();
 34	
 35	    for item in &mut input.items {
 36	        let TraitItem::Fn(func) = item else {
 37	            continue;
 38	        };
 39	
 40	        let cfg_attrs = func
 41	            .attrs
 42	            .iter()
 43	            .filter(|attr| {
 44	                attr.path().is_ident("cfg") || attr.path().is_ident("cfg_attr")
 45	            })
 46	            .cloned()
 47	            .collect::<Vec<_>>();
 48	        let mut override_fn_name = None;
 49	        for attr in mem::take(&mut func.attrs) {
 50	            if attr.path().is_ident("selector") {
 51	                if override_fn_name.is_some() {
 52	                    error!(attr.path(), "more than one selector attribute");
 53	                }
 54	                let args: SelectorArgs = match attr.parse_args() {
 55	                    Ok(args) => args,
 56	                    Err(error) => error!(attr.path(), "{}", error),
 57	                };
 58	                override_fn_name = Some(args.name);
 59	            } else {
 60	                // Put back any other attributes.
 61	                func.attrs.push(attr);
 62	            }
 63	        }
 64	
 65	        let rust_fn_name = func.sig.ident.to_string();
 66	
 67	        let solidity_fn_name =
 68	            override_fn_name.unwrap_or(rust_fn_name.to_case(Case::Camel));
 69	
 70	        let arg_types = func.sig.inputs.iter().filter_map(|arg| match arg {
 71	            FnArg::Typed(t) => Some(t.ty.clone()),
 72	            // Opt out any `self` arguments.
 73	            FnArg::Receiver(_) => None,
 74	        });
 75	
 76	        // Build the function signature string for selector computation.
 77	        let type_strings: Vec<String> =
 78	            arg_types.clone().map(|ty| quote!(#ty).to_string()).collect();
 79	        let uses_self_type = arg_types.clone().any(|ty| type_uses_self(&ty));
 80	        let signature =
 81	            format!("{}({})", solidity_fn_name, type_strings.join(","));
 82	
 83	        let selector_bytes = quote! { stylus_sdk::function_selector!(#solidity_fn_name #(, #arg_types )*) };
 84	        let selector =
 85	            quote! { alloy_primitives::aliases::B32::new(#selector_bytes) };
 86	
 87	        let method_selector = MethodSelector {
 88	            signature: signature.clone(),
 89	            rust_fn_name: rust_fn_name.clone(),
 90	            selector_bytes,
 91	            selector,
 92	            cfg_attrs,
 93	            dynamic: has_trait_generics || uses_self_type,
 94	        };
