 96	        // Report unconditional signature collisions immediately. Conditional
 97	        // methods are checked in generated code so inactive methods do not
 98	        // affect the interface ID or make their collision checks unconditional.
 99	        if let Some(existing) = selectors.iter().find(|existing| {
100	            existing.signature == signature
101	                && existing.cfg_attrs.is_empty()
102	                && method_selector.cfg_attrs.is_empty()
103	        }) {
104	            error!(
105	                    existing.rust_fn_name,
106	                    "selector collision detected: function '{}' has the same selector as function '{}': {}",
107	                    rust_fn_name,
108	                    existing.rust_fn_name,
109	                    signature,
110	                );
111	        };
112	
113	        selectors.push(method_selector);
114	    }
115	
116	    let name = input.ident;
117	    let vis = input.vis;
118	    let attrs = input.attrs;
119	    let trait_items = input.items;
120	    let generics = input.generics.clone();
121	    let where_clause = &generics.where_clause;
122	    let cfg_attrs = attrs
123	        .iter()
124	        .filter(|attr| {
