 105	#[must_use]
 106	pub const fn sbb(a: Limb, b: Limb, borrow: bool) -> (Limb, bool) {
 107	    let a = a as WideLimb;
 108	    let b = b as WideLimb;
 109	    let borrow = borrow as WideLimb;
