170	        new_implementation: Address,
171	        data: &Bytes,
172	    ) -> Result<(), Error> {
173	        Erc1967Utils::set_implementation(context, new_implementation)?;
174	
175	        context
176	            .vm()
177	            .log(erc1967::Upgraded { implementation: new_implementation });
178	
179	        if data.is_empty() {
180	            Erc1967Utils::check_non_payable(context)?;
181	        } else {
182	            AddressUtils::function_delegate_call(
183	                context,
184	                new_implementation,
185	                data.as_ref(),
186	            )?;
187	        }
188	
189	        Ok(())
190	    }
