107	/// Calls `ecRecover` EVM precompile.
108	///
109	/// The `ecRecover` EVM precompile allows for malleable (non-unique) signatures:
110	/// this function rejects them by requiring the `s` value to be in the lower
111	/// half order, and the `v` value to be either 27 or 28.
112	///
113	/// # Arguments
114	///
115	/// * `context` - Execution context for making static calls.
116	/// * `hash` - Hash of the message.
117	/// * `v` - `v` value from the signature.
118	/// * `r` - `r` value from the signature.
119	/// * `s` - `s` value from the signature.
120	///
121	/// # Errors
122	///
123	/// * [`Error::InvalidSignature`] - If the recovered address is
124	///   [`Address::ZERO`].
125	///
126	/// # Panics
127	///
128	/// * If the `ecRecover` precompile fails to execute.
129	fn _recover(
130	    context: &impl HostAccess,
131	    hash: B256,
132	    v: u8,
133	    r: B256,
134	    s: B256,
135	) -> Result<Address, Error> {
136	    let calldata = encode_calldata(hash, v, r, s);
137	
138	    if v == 0 || v == 1 {
139	        // `ecRecover` panics for these values but following the Solidity tests
140	        // https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/test/utils/cryptography/ECDSA.test.js
141	        // it should return `ECDSAInvalidSignature` error.
142	        return Err(ECDSAInvalidSignature {}.into());
143	    }
144	
145	    let recovered =
146	        call::static_call(context.vm(), Call::new(), ECRECOVER_ADDR, &calldata)
147	            .expect("should call `ecRecover` precompile");
148	
149	    let recovered = Address::from_slice(&recovered[12..]);
150	
151	    if recovered.is_zero() {
152	        return Err(ECDSAInvalidSignature {}.into());
153	    }
154	    Ok(recovered)
155	}
