162	/// * `v` - `v` value from the signature.
163	/// * `r` - `r` value from the signature.
164	/// * `s` - `s` value from the signature.
165	fn encode_calldata(hash: B256, v: u8, r: B256, s: B256) -> Vec<u8> {
166	    let calldata = EcRecoverData { hash, v, r, s };
167	    EcRecoverData::abi_encode(&calldata)
