 62	impl<P: PoseidonParams<F>, F: PrimeField> Poseidon2<P, F> {
 63	    /// Create a new Poseidon sponge.
 64	    ///
 65	    /// # Panics
 66	    ///
 67	    /// Panics if `P::D` is not greater than one or is not coprime to the field
 68	    /// order, because then the S-box is not a permutation.
 69	    #[must_use]
 70	    #[inline]
 71	    pub fn new() -> Self {
 72	        assert!(
 73	            Self::sbox_exponent_is_permutation(),
 74	            "Poseidon S-box exponent must be greater than one and coprime to the field order"
 75	        );
 76	
 77	        Self {
 78	            phantom: core::marker::PhantomData,
 79	            state: vec![F::zero(); P::T].into_boxed_slice(),
 80	            mode: Mode::Absorbing,
 81	            // Begin index from `CAPACITY`. Skip capacity elements.
 82	            index: P::CAPACITY,
 83	        }
 84	    }
 85	
 86	    /// Check whether raising to `P::D` is a permutation of the field.
 87	    #[inline]
 88	    fn sbox_exponent_is_permutation() -> bool {
 89	        let degree = u16::from(P::D);
 90	        if degree <= 1 {
 91	            return false;
 92	        }
 93	
 94	        // x -> x^D is a permutation of F_p exactly when gcd(D, p - 1) = 1.
 95	        // Reduce p modulo D while iterating over its bits, avoiding conversion
 96	        // of the field modulus to a machine-sized integer.
 97	        let modulus_mod_degree =
 98	            F::MODULUS.bit_be_trimmed_iter().fold(0u16, |remainder, bit| {
 99	                (remainder * 2 + u16::from(bit)) % degree
100	            });
101	        let mut left = degree;
102	        let mut right = (modulus_mod_degree + degree - 1) % degree;
103	        while right != 0 {
104	            (left, right) = (right, left % right);
105	        }
106	        left == 1
107	    }
