 15	struct MethodSelector {
 16	    signature: String,
 17	    rust_fn_name: String,
 18	    selector_bytes: proc_macro2::TokenStream,
 19	    selector: proc_macro2::TokenStream,
 20	    cfg_attrs: Vec<Attribute>,
 21	    dynamic: bool,
 22	}
 23	
 24	/// Computes an interface id as an associated function for the trait.
 25	pub(crate) fn interface_id(
 26	    _attr: &TokenStream,
 27	    input: TokenStream,
 28	) -> TokenStream {
 29	    let mut input = parse_macro_input!(input as ItemTrait);
 30	
 31	    let unsafety = input.unsafety;
 32	    let mut selectors = Vec::<MethodSelector>::new();
 33	    let has_trait_generics = !input.generics.params.is_empty();
 34	
 35	    for item in &mut input.items {
 36	        let TraitItem::Fn(func) = item else {
 37	            continue;
 38	        };
 39	
 40	        let cfg_attrs = func
 41	            .attrs
 42	            .iter()
 43	            .filter(|attr| {
 44	                attr.path().is_ident("cfg") || attr.path().is_ident("cfg_attr")
 45	            })
 46	            .cloned()
 47	            .collect::<Vec<_>>();
 48	        let mut override_fn_name = None;
 49	        for attr in mem::take(&mut func.attrs) {
 50	            if attr.path().is_ident("selector") {
 51	                if override_fn_name.is_some() {
 52	                    error!(attr.path(), "more than one selector attribute");
 53	                }
 54	                let args: SelectorArgs = match attr.parse_args() {
 55	                    Ok(args) => args,
 56	                    Err(error) => error!(attr.path(), "{}", error),
 57	                };
 58	                override_fn_name = Some(args.name);
 59	            } else {
 60	                // Put back any other attributes.
 61	                func.attrs.push(attr);
 62	            }
 63	        }
 64	
 65	        let rust_fn_name = func.sig.ident.to_string();
 66	
 67	        let solidity_fn_name =
 68	            override_fn_name.unwrap_or(rust_fn_name.to_case(Case::Camel));
 69	
 70	        let arg_types = func.sig.inputs.iter().filter_map(|arg| match arg {
 71	            FnArg::Typed(t) => Some(t.ty.clone()),
 72	            // Opt out any `self` arguments.
 73	            FnArg::Receiver(_) => None,
 74	        });
 75	
 76	        // Build the function signature string for selector computation.
 77	        let type_strings: Vec<String> =
 78	            arg_types.clone().map(|ty| quote!(#ty).to_string()).collect();
 79	        let uses_self_type = arg_types.clone().any(|ty| type_uses_self(&ty));
 80	        let signature =
 81	            format!("{}({})", solidity_fn_name, type_strings.join(","));
 82	
 83	        let selector_bytes = quote! { stylus_sdk::function_selector!(#solidity_fn_name #(, #arg_types )*) };
 84	        let selector =
 85	            quote! { alloy_primitives::aliases::B32::new(#selector_bytes) };
 86	
 87	        let method_selector = MethodSelector {
 88	            signature: signature.clone(),
 89	            rust_fn_name: rust_fn_name.clone(),
 90	            selector_bytes,
 91	            selector,
 92	            cfg_attrs,
 93	            dynamic: has_trait_generics || uses_self_type,
 94	        };
 95	
 96	        // Report unconditional signature collisions immediately. Conditional
 97	        // methods are checked in generated code so inactive methods do not
 98	        // affect the interface ID or make their collision checks unconditional.
 99	        if let Some(existing) = selectors.iter().find(|existing| {
100	            existing.signature == signature
101	                && existing.cfg_attrs.is_empty()
102	                && method_selector.cfg_attrs.is_empty()
103	        }) {
104	            error!(
105	                    existing.rust_fn_name,
106	                    "selector collision detected: function '{}' has the same selector as function '{}': {}",
107	                    rust_fn_name,
108	                    existing.rust_fn_name,
109	                    signature,
110	                );
111	        };
112	
113	        selectors.push(method_selector);
114	    }
115	
116	    let name = input.ident;
117	    let vis = input.vis;
118	    let attrs = input.attrs;
119	    let trait_items = input.items;
120	    let generics = input.generics.clone();
121	    let where_clause = &generics.where_clause;
122	    let cfg_attrs = attrs
123	        .iter()
124	        .filter(|attr| {
125	            attr.path().is_ident("cfg") || attr.path().is_ident("cfg_attr")
126	        })
127	        .cloned()
128	        .collect::<Vec<_>>();
129	
130	    let mut module_selector_checks = Vec::new();
131	    let mut method_selector_checks = Vec::new();
132	    for (index, selector_a) in selectors.iter().enumerate() {
133	        for selector_b in &selectors[index + 1..] {
134	            let message = LitStr::new(
135	                &format!(
136	                    "selector collision detected: '{}' and '{}' have the same selector",
137	                    selector_a.signature, selector_b.signature
138	                ),
139	                proc_macro2::Span::call_site(),
140	            );
141	            let selector_bytes_a = &selector_a.selector_bytes;
142	            let selector_bytes_b = &selector_b.selector_bytes;
143	            let cfg_attrs_a = &selector_a.cfg_attrs;
144	            let cfg_attrs_b = &selector_b.cfg_attrs;
145	            let check = if selector_a.dynamic || selector_b.dynamic {
146	                quote! {
147	                    #(#cfg_attrs_a)*
148	                    #(#cfg_attrs_b)*
149	                    const {
150	                        assert!(
151	                            u32::from_be_bytes(#selector_bytes_a)
152	                                != u32::from_be_bytes(#selector_bytes_b),
153	                            #message,
154	                        );
155	                    };
156	                }
157	            } else {
158	                quote! {
159	                    #(#cfg_attrs)*
160	                    #(#cfg_attrs_a)*
161	                    #(#cfg_attrs_b)*
162	                    const _: () = {
163	                        assert!(
164	                            u32::from_be_bytes(#selector_bytes_a)
165	                                != u32::from_be_bytes(#selector_bytes_b),
166	                            #message,
167	                        );
168	                    };
169	                }
170	            };
171	
172	            if selector_a.dynamic || selector_b.dynamic {
173	                method_selector_checks.push(check);
174	            } else {
175	                module_selector_checks.push(check);
176	            }
177	        }
178	    }
179	
180	    let supertrait_tokens = if input.supertraits.is_empty() {
181	        quote! {}
182	    } else {
183	        let supertraits = &input.supertraits;
184	        quote! { : #supertraits }
185	    };
186	
187	    let selector_xors = selectors.iter().map(|selector| {
188	        let attrs = &selector.cfg_attrs;
189	        let value = &selector.selector;
190	        quote! {
191	            #(#attrs)*
192	            let __interface_id = __interface_id ^ #value;
193	        }
194	    });
195	
196	    // Keep the same trait with an additional associated function
197	    // `interface_id`.
198	    quote! {
199	        #(#module_selector_checks)*
200	        #(#attrs)*
201	        #vis #unsafety trait #name #generics #supertrait_tokens #where_clause {
202	            #(#trait_items)*
203	
204	            #[doc = concat!("Solidity interface id associated with ", stringify!(#name), " trait.")]
205	            #[doc = "Computed as a XOR of selectors for each function in the trait."]
206	            fn interface_id() -> alloy_primitives::aliases::B32
207	            where
208	                Self: Sized,
209	            {
210	                let __interface_id =
211	                    alloy_primitives::aliases::B32::new([0; 4]);
212	                #(#method_selector_checks)*
213	                #(#selector_xors)*
214	                __interface_id
215	            }
216	        }
217	    }
218	    .into()
219	}
