121	    ///
122	    /// let proof_flags = [false, true, false, true];
123	    ///
124	    /// let verification =
125	    ///     Verifier::verify_multi_proof(&proof, &proof_flags, root, &leaves);
126	    /// assert!(verification.unwrap());
127	    /// ```
