221	/// Whether a selector argument type depends on the trait's `Self` type.
222	fn type_uses_self(ty: &syn::Type) -> bool {
223	    fn contains_self(tokens: proc_macro2::TokenStream) -> bool {
224	        tokens.into_iter().any(|token| match token {
225	            TokenTree::Ident(ident) => ident == "Self",
226	            TokenTree::Group(group) => contains_self(group.stream()),
227	            _ => false,
228	        })
229	    }
230	
231	    contains_self(quote!(#ty))
232	}
