541	impl UUPSUpgradeable {
542	    /// Performs an implementation upgrade with a security check for UUPS
543	    /// proxies, and additional setup call.
544	    ///
545	    /// As a security check, [`IErc1822Proxiable::proxiable_uuid`] is invoked
546	    /// in the new implementation, and the return value is expected to be the
547	    /// implementation slot in ERC-1967.
548	    ///
549	    /// # Arguments
550	    ///
551	    /// * `&mut self` - Write access to the contract's state.
552	    /// * `new_implementation` - The address of the new implementation.
553	    /// * `data` - The data to pass to the new implementation.
554	    ///
555	    /// # Errors
556	    ///
557	    /// * [`Error::InvalidImplementation`] - If the new implementation doesn't
558	    ///   support the required interface or is invalid.
559	    /// * [`Error::UnsupportedProxiableUUID`] - If the new implementation
560	    ///   returns an unsupported UUID.
561	    /// * [`Error::NonPayable`] - If the upgrade function receives ETH but is
562	    ///   not designed to handle it.
563	    /// * [`Error::EmptyCode`] - If there's no code at the new implementation
564	    ///   address.
565	    /// * [`Error::FailedCall`] - If the [`delegate_call`][delegate_call] to the
566	    ///   new implementation fails.
567	    /// * [`Error::FailedCallWithReason`] - If the
568	    ///   [`stylus_sdk::call::delegate_call`] fails with a specific reason.
569	    ///
570	    /// # Events
571	    ///
572	    /// * [`crate::proxy::erc1967::Erc1967Proxy::Upgraded`]: Emitted when the
573	    ///   implementation is upgraded.
574	    ///
575	    /// [delegate_call]: stylus_sdk::call::delegate_call
576	    fn _upgrade_to_and_call_uups(
577	        &mut self,
578	        new_implementation: Address,
579	        data: &Bytes,
580	    ) -> Result<(), Error> {
581	        let slot = Erc1822ProxiableInterface::new(new_implementation)
582	            .proxiable_uuid(self.vm(), Call::new())
583	            .map_err(|_e| {
584	                Error::InvalidImplementation(ERC1967InvalidImplementation {
585	                    implementation: new_implementation,
586	                })
587	            })?;
588	
589	        if slot == IMPLEMENTATION_SLOT {
590	            Erc1967Utils::upgrade_to_and_call(self, new_implementation, data)
591	                .map_err(Error::from)
592	        } else {
593	            Err(Error::UnsupportedProxiableUUID(UUPSUnsupportedProxiableUUID {
594	                slot,
595	            }))
596	        }
597	    }
598	}
