237	    /// # Errors
238	    ///
239	    /// * [`Error::InvalidBeacon`] - If the `new_beacon` address is not a valid
240	    ///   beacon.
241	    /// * [`Error::InvalidImplementation`] - If the beacon implementation is not
242	    ///   a valid implementation.
243	    /// * [`Error::NonPayable`] - If `data` is empty and the VM call value is not
244	    ///   [`U256::ZERO`].
245	    /// * [`Error::FailedCall`] - If the call to the beacon implementation
246	    ///   fails.
247	    /// * [`Error::FailedCallWithReason`] - If the call to the beacon
248	    ///   implementation fails with a revert reason.
249	    pub fn upgrade_beacon_to_and_call<
250	        T: TopLevelStorage + HostAccess<Host = VM>,
251	    >(
252	        context: &mut T,
253	        new_beacon: Address,
254	        data: &Bytes,
255	    ) -> Result<(), Error> {
256	        Erc1967Utils::set_beacon(context, new_beacon)?;
257	        context.vm().log(erc1967::BeaconUpgraded { beacon: new_beacon });
258	
259	        if data.is_empty() {
260	            Erc1967Utils::check_non_payable(context)?;
261	        } else {
262	            let beacon_implementation =
263	                Erc1967Utils::get_beacon_implementation(context, new_beacon)?;
264	
265	            AddressUtils::function_delegate_call(
266	                context,
267	                beacon_implementation,
268	                data.as_ref(),
269	            )?;
270	        }
271	
272	        Ok(())
273	    }
274	}
