460	    /// Ensures the call is being made through a valid [ERC-1967] proxy.
461	    ///
462	    /// Checks:
463	    /// 1. Execution is happening via [`delegate_call`][delegate_call] (checked
464	    ///    via `!self.is_logic()`).
465	    /// 2. The caller is a valid [ERC-1967] proxy (implementation slot is
466	    ///    non-zero).
467	    /// 3. The proxy state is consistent for this logic (the proxy-stored
468	    ///    version equals this logic's `VERSION_NUMBER`).
469	    ///
470	    /// [`onlyProxy`]: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/c64a1edb67b6e3f4a15cca8909c9482ad33a02b0/contracts/proxy/utils/UUPSUpgradeable.sol#L50
471	    ///
472	    /// # Security Implications
473	    ///
474	    /// This check prevents direct calls to upgrade functions on the
475	    /// implementation contract.
476	    ///
477	    /// Note: This is not a reentrancy guard. Use a dedicated mechanism if
478	    /// reentrancy protection is required.
479	    ///
480	    /// # Edge Cases
481	    ///
482	    /// * Calls from [ERC-1167] minimal proxies are not guaranteed to pass this
483	    ///   check
484	    ///
485	    /// # Arguments
486	    ///
487	    /// * `&self` - Read access to the contract's state.
488	    ///
489	    /// # Errors
490	    ///
491	    /// * [`Error::UnauthorizedCallContext`] - If any of the above conditions is
492	    ///   not met
493	    ///
494	    /// [ERC-1967]: https://eips.ethereum.org/EIPS/eip-1967
495	    /// [ERC-1167]: https://eips.ethereum.org/EIPS/eip-1167
496	    /// [delegate_call]: stylus_sdk::call::delegate_call
497	    pub fn only_proxy(&self) -> Result<(), Error> {
498	        if self.is_logic()
499	            || Erc1967Utils::get_implementation(self) == Address::ZERO
500	            || U32::from(self.get_version()) != self.version.get()
501	        {
502	            Err(Error::UnauthorizedCallContext(UUPSUnauthorizedCallContext {}))
503	        } else {
504	            Ok(())
505	        }
506	    }
