521	    ///   [`delegate_call`].
522	    ///
523	    /// [`delegate_call`]: stylus_sdk::call::delegate_call
524	    pub fn not_delegated(&self) -> Result<(), Error> {
525	        if self.is_logic() {
526	            Ok(())
527	        } else {
528	            Err(Error::UnauthorizedCallContext(UUPSUnauthorizedCallContext {}))
529	        }
530	    }
