174	    ///   contract.
175	    ///
176	    /// # Events
177	    ///
178	    /// * [`Upgraded`].
179	    fn set_implementation(
180	        &mut self,
181	        new_implementation: Address,
182	    ) -> Result<(), Error> {
183	        if self.vm().code_size(new_implementation) == 0 {
184	            return Err(Error::InvalidImplementation(
