112	/// Clamps the given little-endian representation of a 32-byte integer.
113	///
114	/// Clamping the value puts it in the range:
115	/// **n ∈ 2^254 + 8\*{0, 1, 2, 3, ..., 2^251 − 1}**
116	///
117	/// # Explanation of clamping
118	///
119	/// For Curve25519, h = 8, and multiplying by 8 is the same as a binary
120	/// left-shift by 3 bits. If you take a secret scalar value between 2^251 and
121	/// 2^252 – 1 and left-shift by 3 bits, then you end up with a 255-bit number
122	/// with the most significant bit set to 1 and the least-significant three bits
123	/// set to 0.
124	///
125	/// The Curve25519 clamping operation takes **an arbitrary 256-bit random
126	/// value** and clears the most-significant bit (making it a 255-bit number),
127	/// sets the next bit, and then clears the 3 least-significant bits. In other
128	/// words, it directly creates a scalar value that is in the right form and
129	/// pre-multiplied by the cofactor.
130	///
131	/// See [clamping reference] for more details.
132	///
133	/// [clamping reference]: https://neilmadden.blog/2020/05/28/whats-the-curve25519-clamping-all-about/
134	#[must_use]
135	pub const fn clamp_integer(mut bytes: [u8; 32]) -> [u8; 32] {
136	    bytes[0] &= 0b1111_1000;
137	    bytes[31] &= 0b0111_1111;
138	    bytes[31] |= 0b0100_0000;
139	    bytes
140	}
