332	/// Ed25519 key for signature verification (public key).
333	#[derive(Copy, Clone, PartialEq)]
334	pub struct VerifyingKey {
335	    /// Edwards point used for curve arithmetic operations.
336	    point: ProjectivePoint,
337	    is_valid: bool,
338	}
339	
340	impl VerifyingKey {
341	    /// Construct verifying key from affine point.
342	    ///
343	    /// Points outside the non-identity prime-order subgroup create an invalid
344	    /// key. [`Self::is_valid`] returns `false` for signatures checked with an
345	    /// invalid key.
346	    #[must_use]
347	    pub fn from_affine(point: AffinePoint) -> Self {
348	        let is_valid = !point.is_zero()
349	            && point.is_on_curve()
350	            && point.is_in_prime_order_subgroup();
351	        VerifyingKey { point: point.into(), is_valid }
352	    }
353	
354	    /// Returns whether this key is a non-identity point in the prime-order
355	    /// subgroup.
356	    #[must_use]
357	    pub const fn is_valid_key(&self) -> bool {
358	        self.is_valid
359	    }
360	
361	    /// Returns the Edwards point for this key.
362	    #[must_use]
363	    pub const fn point(&self) -> ProjectivePoint {
364	        self.point
365	    }
366	
367	    /// Verify a signature on a message with this keypair's public key.
368	    #[must_use]
369	    pub fn is_valid(&self, message: &[u8], signature: &Signature) -> bool {
370	        if !self.is_valid {
371	            return false;
372	        }
373	
374	        let expected_r = self.compute_R(signature, message);
375	        expected_r == signature.R
376	    }
377	
378	    /// Helper for verification. Computes the expected `R` component of the
379	    /// signature. The caller compares this to the real `R` component.
380	    /// This computes `H(R || A || M)` where `H` is the 512-bit hash function
381	    /// given by `CtxDigest` (this is SHA-512 in spec-compliant Ed25519).
382	    fn compute_R(
383	        &self,
384	        signature: &Signature,
385	        message: &[u8],
386	    ) -> ProjectivePoint {
387	        let R = signature.R;
388	        let A = self.point;
389	
390	        let mut h = Sha512::new();
391	        h.update(CompressedPointY::from(R.into_affine()));
392	        h.update(CompressedPointY::from(A.into_affine()));
393	        h.update(message);
394	
395	        let k = WideScalar::from_bigint(U512::from_bytes_le(
396	            h.finalize().as_slice(),
397	        ));
398	        let k = Scalar::from_fp(k);
399	
400	        // Compute R: `-[k]A + [s]B = R`.
401	        A * (-k) + ProjectivePoint::generator() * signature.s
402	    }
403	
404	    /// Convert the [`VerifyingKey`] to a compressed byte representation.
405	    #[inline]
406	    #[must_use]
407	    pub fn to_bytes(&self) -> PublicKey {
408	        CompressedPointY::from(self.point.into_affine()).into()
409	    }
410	}
411	
412	impl Default for VerifyingKey {
413	    fn default() -> Self {
414	        VerifyingKey { point: ProjectivePoint::default(), is_valid: false }
415	    }
416	}
417	
418	impl From<ProjectivePoint> for VerifyingKey {
419	    fn from(point: ProjectivePoint) -> Self {
420	        let is_valid_projective = !point.is_zero()
421	            && !point.z.is_zero()
422	            && point.t * point.z == point.x * point.y;
423	        if !is_valid_projective {
424	            return VerifyingKey::default();
425	        }
426	
427	        VerifyingKey::from_affine(point.into_affine())
428	    }
429	}
430	
431	impl From<ExpandedSecretKey> for VerifyingKey {
432	    fn from(value: ExpandedSecretKey) -> Self {
433	        let point = ProjectivePoint::generator() * value.scalar;
434	        VerifyingKey { point, is_valid: !point.is_zero() }
435	    }
436	}
