 24	/// Field for the domain separator.
 25	const FIELDS: [u8; 1] = [0x0f];
 26	
 27	/// Salt for the domain separator.
 28	const SALT: [u8; 32] = [0u8; 32];
 29	
 30	/// Prefix for ERC-191 version with `0x01`.
 31	const TYPED_DATA_PREFIX: [u8; 2] = [0x19, 0x01];
 32	
 33	/// Tuple for the domain separator.
 34	type DomainSeparatorTuple = sol! {
 35	    tuple(bytes32, bytes32, bytes32, uint256, address)
 36	};
 37	
 38	/// Returns the keccak256 digest of an EIP-712 typed data (ERC-191 version
 39	/// `0x01`).
 40	///
 41	/// The digest is calculated from a `domain_separator` and a `struct_hash`, by
 42	/// prefixing them with `[TYPED_DATA_PREFIX]` and hashing the result. It
 43	/// corresponds to the hash signed by the [eth_signTypedData] JSON-RPC method as
 44	/// part of EIP-712.
 45	///
 46	/// [eth_signTypedData]: https://eips.ethereum.org/EIPS/eip-712
 47	#[must_use]
 48	pub fn to_typed_data_hash(
 49	    domain_separator: &[u8; 32],
 50	    struct_hash: &[u8; 32],
 51	) -> B256 {
 52	    let mut preimage = [0u8; 66];
 53	    preimage[..2].copy_from_slice(&TYPED_DATA_PREFIX);
 54	    preimage[2..34].copy_from_slice(domain_separator);
 55	    preimage[34..].copy_from_slice(struct_hash);
 56	    keccak256(preimage)
 57	}
