 59	/// EIP-712 Contract interface.
 60	pub trait IEip712 {
 61	    /// Immutable name of EIP-712 instance.
 62	    const NAME: &'static str;
 63	    /// Hashed name of EIP-712 instance.
 64	    const HASHED_NAME: [u8; 32] =
 65	        keccak_const::Keccak256::new().update(Self::NAME.as_bytes()).finalize();
 66	
 67	    /// Immutable version of EIP-712 instance.
 68	    const VERSION: &'static str;
 69	    /// Hashed version of EIP-712 instance.
 70	    const HASHED_VERSION: [u8; 32] = keccak_const::Keccak256::new()
 71	        .update(Self::VERSION.as_bytes())
 72	        .finalize();
 73	
 74	    /// Returns chain id.
 75	    #[must_use]
 76	    fn chain_id(&self) -> U256;
 77	
 78	    /// Returns the contract's address.
 79	    #[must_use]
 80	    fn contract_address(&self) -> Address;
 81	
 82	    /// Returns the fields and values that describe the domain separator used by
 83	    /// this contract for EIP-712 signature.
 84	    ///
 85	    /// # Arguments
 86	    ///
 87	    /// * `&self` - Read access to the contract's state.
 88	    fn eip712_domain(
 89	        &self,
 90	    ) -> ([u8; 1], String, String, U256, Address, [u8; 32], Vec<U256>) {
 91	        (
 92	            FIELDS,
 93	            Self::NAME.to_owned(),
 94	            Self::VERSION.to_owned(),
 95	            self.chain_id(),
 96	            self.contract_address(),
 97	            SALT,
 98	            Vec::new(),
 99	        )
100	    }
101	
102	    /// Returns the domain separator for the current chain.
103	    ///
104	    /// # Arguments
105	    ///
106	    /// * `&self` - Read access to the contract's state.
107	    fn domain_separator_v4(&self) -> B256 {
108	        let encoded = DomainSeparatorTuple::abi_encode(&(
109	            TYPE_HASH,
110	            Self::HASHED_NAME,
111	            Self::HASHED_VERSION,
112	            self.chain_id(),
113	            self.contract_address(),
114	        ));
115	
116	        keccak256(encoded)
117	    }
118	
119	    /// Given an already [hashed struct], this function returns the hash of the
120	    /// fully encoded EIP-712 message for this domain.
121	    ///
122	    /// [hashed struct]: https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct
123	    ///
124	    /// # Arguments
125	    ///
126	    /// * `&self` - Read access to the contract's state.
127	    fn hash_typed_data_v4(&self, struct_hash: B256) -> B256 {
128	        let domain_separator = self.domain_separator_v4();
129	        to_typed_data_hash(&domain_separator, &struct_hash)
130	    }
131	}
