150	/// Ed25519 signing key which can be used to produce signatures.
151	///
152	/// Invariant: `verifying_key` is always the public key of
153	/// `secret_key`.
154	/// This prevents the signing function [oracle attack].
155	///
156	/// [oracle attack]: https://github.com/MystenLabs/ed25519-unsafe-libs
157	#[derive(Clone, PartialEq)]
158	pub struct SigningKey {
159	    /// The secret half of this signing key.
160	    pub(crate) signing_key: ExpandedSecretKey,
161	    /// The public half of this signing key.
162	    pub(crate) verifying_key: VerifyingKey,
163	}
164	
165	impl SigningKey {
166	    /// Get the [`VerifyingKey`] for this [`SigningKey`].
167	    #[must_use]
168	    pub fn verifying_key(&self) -> VerifyingKey {
169	        self.verifying_key
170	    }
171	
172	    /// Construct a [`SigningKey`] from a [`SecretKey`].
173	    #[inline]
174	    #[must_use]
175	    pub fn from_bytes(secret_key: &SecretKey) -> Self {
176	        let signing_key: ExpandedSecretKey = secret_key.into();
177	        let verifying_key: VerifyingKey = signing_key.clone().into();
178	        Self { signing_key, verifying_key }
179	    }
180	
181	    /// Verify a signature on a message with this signing key's public key.
182	    #[must_use]
183	    pub fn is_valid_signature(
184	        &self,
185	        message: &[u8],
186	        signature: &Signature,
187	    ) -> bool {
188	        self.verifying_key.is_valid(message, signature)
189	    }
190	
191	    /// Sign a message with this signing key's secret key.
192	    ///
193	    /// ```rust
194	    ///  use openzeppelin_crypto::eddsa::{SecretKey, SigningKey, SECRET_KEY_LENGTH};
195	    ///
196	    ///  let secret_key: SecretKey = [1u8; SECRET_KEY_LENGTH];
197	    ///  let signing_key = SigningKey::from_bytes(&secret_key);
198	    ///  let message = b"Sign me!";
199	    ///
200	    ///  let signature = signing_key.sign(message);
201	    ///  assert!(signing_key.is_valid_signature(message, &signature));
202	    /// ```
203	    #[must_use]
204	    pub fn sign(&self, message: &[u8]) -> Signature {
205	        let mut h = Sha512::new();
206	
207	        h.update(self.signing_key.hash_prefix);
208	        h.update(message);
209	
210	        let r = WideScalar::from_bigint(U512::from_bytes_le(
211	            h.finalize().as_slice(),
212	        ));
213	        let r = Scalar::from_fp(r);
214	
215	        let R = ProjectivePoint::generator() * r;
216	
217	        h = Sha512::new();
218	        h.update(CompressedPointY::from(R.into_affine()));
219	        h.update(CompressedPointY::from(
220	            self.verifying_key.point.into_affine(),
221	        ));
222	        h.update(message);
223	
224	        let k = WideScalar::from_bigint(U512::from_bytes_le(
225	            h.finalize().as_slice(),
226	        ));
227	        let k = Scalar::from_fp(k);
228	        let s: Scalar = (k * self.signing_key.scalar) + r;
229	
230	        Signature { R, s }
231	    }
232	}
