  1	//! [EIP-712](https://eips.ethereum.org/EIPS/eip-712) is a standard for hashing
  2	//! and signing typed structured data.
  3	//!
  4	//! The implementation of the domain separator was designed to be as efficient
  5	//! as possible while still properly updating the chain id to protect against
  6	//! replay attacks on an eventual fork of the chain.
  7	//!
  8	//! NOTE: This contract implements the version of the encoding known as "v4", as
  9	//! implemented by the JSON RPC method [`eth_signTypedDataV4`] in `MetaMask`.
 10	//!
 11	//! [`eth_signTypedDataV4`]: https://docs.metamask.io/guide/signing-data.html
 12	
 13	use alloc::{borrow::ToOwned, string::String, vec::Vec};
 14	
 15	use alloy_primitives::{keccak256, Address, B256, U256};
 16	use alloy_sol_types::{sol, SolType};
 17	
 18	/// Keccak-256 hash of the EIP-712 domain separator type string.
 19	const TYPE_HASH: [u8; 32] =
 20	    keccak_const::Keccak256::new()
 21	        .update(b"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)")
 22	        .finalize();
 23	
 24	/// Field for the domain separator.
 25	const FIELDS: [u8; 1] = [0x0f];
 26	
 27	/// Salt for the domain separator.
 28	const SALT: [u8; 32] = [0u8; 32];
 29	
 30	/// Prefix for ERC-191 version with `0x01`.
 31	const TYPED_DATA_PREFIX: [u8; 2] = [0x19, 0x01];
 32	
 33	/// Tuple for the domain separator.
 34	type DomainSeparatorTuple = sol! {
 35	    tuple(bytes32, bytes32, bytes32, uint256, address)
 36	};
 37	
 38	/// Returns the keccak256 digest of an EIP-712 typed data (ERC-191 version
 39	/// `0x01`).
 40	///
 41	/// The digest is calculated from a `domain_separator` and a `struct_hash`, by
 42	/// prefixing them with `[TYPED_DATA_PREFIX]` and hashing the result. It
 43	/// corresponds to the hash signed by the [eth_signTypedData] JSON-RPC method as
 44	/// part of EIP-712.
 45	///
 46	/// [eth_signTypedData]: https://eips.ethereum.org/EIPS/eip-712
 47	#[must_use]
 48	pub fn to_typed_data_hash(
 49	    domain_separator: &[u8; 32],
 50	    struct_hash: &[u8; 32],
 51	) -> B256 {
 52	    let mut preimage = [0u8; 66];
 53	    preimage[..2].copy_from_slice(&TYPED_DATA_PREFIX);
 54	    preimage[2..34].copy_from_slice(domain_separator);
 55	    preimage[34..].copy_from_slice(struct_hash);
 56	    keccak256(preimage)
 57	}
 58	
 59	/// EIP-712 Contract interface.
 60	pub trait IEip712 {
 61	    /// Immutable name of EIP-712 instance.
 62	    const NAME: &'static str;
 63	    /// Hashed name of EIP-712 instance.
 64	    const HASHED_NAME: [u8; 32] =
 65	        keccak_const::Keccak256::new().update(Self::NAME.as_bytes()).finalize();
 66	
 67	    /// Immutable version of EIP-712 instance.
 68	    const VERSION: &'static str;
 69	    /// Hashed version of EIP-712 instance.
 70	    const HASHED_VERSION: [u8; 32] = keccak_const::Keccak256::new()
 71	        .update(Self::VERSION.as_bytes())
 72	        .finalize();
 73	
 74	    /// Returns chain id.
 75	    #[must_use]
 76	    fn chain_id(&self) -> U256;
 77	
 78	    /// Returns the contract's address.
 79	    #[must_use]
 80	    fn contract_address(&self) -> Address;
 81	
 82	    /// Returns the fields and values that describe the domain separator used by
 83	    /// this contract for EIP-712 signature.
 84	    ///
 85	    /// # Arguments
 86	    ///
 87	    /// * `&self` - Read access to the contract's state.
 88	    fn eip712_domain(
 89	        &self,
 90	    ) -> ([u8; 1], String, String, U256, Address, [u8; 32], Vec<U256>) {
 91	        (
 92	            FIELDS,
 93	            Self::NAME.to_owned(),
 94	            Self::VERSION.to_owned(),
 95	            self.chain_id(),
 96	            self.contract_address(),
 97	            SALT,
 98	            Vec::new(),
 99	        )
100	    }
101	
102	    /// Returns the domain separator for the current chain.
103	    ///
104	    /// # Arguments
105	    ///
106	    /// * `&self` - Read access to the contract's state.
107	    fn domain_separator_v4(&self) -> B256 {
108	        let encoded = DomainSeparatorTuple::abi_encode(&(
109	            TYPE_HASH,
110	            Self::HASHED_NAME,
111	            Self::HASHED_VERSION,
112	            self.chain_id(),
113	            self.contract_address(),
114	        ));
115	
116	        keccak256(encoded)
117	    }
118	
119	    /// Given an already [hashed struct], this function returns the hash of the
120	    /// fully encoded EIP-712 message for this domain.
121	    ///
122	    /// [hashed struct]: https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct
123	    ///
124	    /// # Arguments
125	    ///
126	    /// * `&self` - Read access to the contract's state.
127	    fn hash_typed_data_v4(&self, struct_hash: B256) -> B256 {
128	        let domain_separator = self.domain_separator_v4();
129	        to_typed_data_hash(&domain_separator, &struct_hash)
130	    }
131	}
