    pub fn deposit(
        &mut self,
        assets: U256,
        receiver: Address,
        erc20: &mut Erc20,
    ) -> Result<U256, Error> {
        let max_assets = self.max_deposit(receiver);

        if assets > max_assets {
            return Err(Error::ExceededMaxDeposit(ERC4626ExceededMaxDeposit {
                receiver,
                assets,
                max: max_assets,
            }));
        }

        let shares = self.preview_deposit(assets, erc20)?;

        self._deposit(self.vm().msg_sender(), receiver, assets, shares, erc20)?;

        Ok(shares)
    }

    /// See [`IErc4626::mint`].
    #[allow(clippy::missing_errors_doc)]
    pub fn mint(
        &mut self,
        shares: U256,
        receiver: Address,
        erc20: &mut Erc20,
    ) -> Result<U256, Error> {
        let max_shares = self.max_mint(receiver);

        if shares > max_shares {
            return Err(Error::ExceededMaxMint(ERC4626ExceededMaxMint {
                receiver,
                shares,
                max: max_shares,
            }));
        }

        let assets = self.preview_mint(shares, erc20)?;
        self._deposit(self.vm().msg_sender(), receiver, assets, shares, erc20)?;

        Ok(assets)
    }

    /// See [`IErc4626::withdraw`].
    #[allow(clippy::missing_errors_doc)]
    pub fn withdraw(
        &mut self,
        assets: U256,
        receiver: Address,
        owner: Address,
        erc20: &mut Erc20,
    ) -> Result<U256, Error> {
        let max_assets = self.max_withdraw(owner, erc20)?;

        if assets > max_assets {
            return Err(Error::ExceededMaxWithdraw(
                ERC4626ExceededMaxWithdraw { owner, assets, max: max_assets },
            ));
        }

        let shares = self.preview_withdraw(assets, erc20)?;
        self._withdraw(
            self.vm().msg_sender(),
            receiver,
            owner,
            assets,
            shares,
            erc20,
        )?;

        Ok(shares)
    }

    /// See [`IErc4626::redeem`].
    #[allow(clippy::missing_errors_doc)]
    pub fn redeem(
        &mut self,
        shares: U256,
        receiver: Address,
        owner: Address,
        erc20: &mut Erc20,
    ) -> Result<U256, Error> {
        let max_shares = self.max_redeem(owner, erc20);
        if shares > max_shares {
            return Err(Error::ExceededMaxRedeem(ERC4626ExceededMaxRedeem {
                owner,
                shares,
                max: max_shares,
            }));
        }

        let assets = self.preview_redeem(shares, erc20)?;

        self._withdraw(
            self.vm().msg_sender(),
            receiver,
            owner,
            assets,
            shares,
            erc20,
        )?;

        Ok(assets)
    }
