#[implements(IAccessControl<Error = Error>, IErc165)]
impl AccessControl {}

#[public]
impl IAccessControl for AccessControl {
    type Error = Error;

    fn has_role(&self, role: B256, account: Address) -> bool {
        self.roles.getter(role).has_role.get(account)
    }

    fn only_role(&self, role: B256) -> Result<(), Self::Error> {
        self._check_role(role, self.vm().msg_sender())
    }

    fn get_role_admin(&self, role: B256) -> B256 {
        self.roles.getter(role).admin_role.get()
    }

    fn grant_role(
        &mut self,
        role: B256,
        account: Address,
    ) -> Result<(), Self::Error> {
        let admin_role = self.get_role_admin(role);
        self.only_role(admin_role)?;
        self._grant_role(role, account);
        Ok(())
    }

    fn revoke_role(
        &mut self,
        role: B256,
        account: Address,
    ) -> Result<(), Self::Error> {
        let admin_role = self.get_role_admin(role);
        self.only_role(admin_role)?;
        self._revoke_role(role, account);
        Ok(())
    }

    fn renounce_role(
        &mut self,
        role: B256,
        confirmation: Address,
    ) -> Result<(), Self::Error> {
        if self.vm().msg_sender() != confirmation {
            return Err(Error::BadConfirmation(
                AccessControlBadConfirmation {},
            ));
        }

        self._revoke_role(role, confirmation);
        Ok(())
    }
}

