        &mut self,
        from: Address,
        to: Address,
        ids: Vec<U256>,
        values: Vec<U256>,
        data: &Bytes,
    ) -> Result<(), Error> {
        self._update(from, to, ids.clone(), values.clone())?;

        if !to.is_zero() {
            self._check_on_erc1155_received(
                self.vm().msg_sender(),
                from,
                to,
                Erc1155ReceiverData::new(ids, values),
                data.to_vec().into(),
            )?;
        }

        Ok(())
    }

    /// Creates a `value` amount of tokens of type `id`, and assigns
