impl Erc1155Supply {
    /// Extended version of [`Erc1155::_update`] that updates the supply of
    /// tokens.
    ///
    /// NOTE: The ERC-1155 acceptance check is not performed in this function.
    /// See [`Self::_update_with_acceptance_check`] instead.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `from` - Account of the sender.
    /// * `to` - Account of the recipient.
    /// * `token_ids` - Array of all token id.
    /// * `values` - Array of all amount of tokens to be supplied.
    ///
    /// # Errors
    ///
    /// * [`erc1155::Error::InvalidArrayLength`] - If length of `ids` is not
    ///   equal to length of `values`.
    /// * [`erc1155::Error::InsufficientBalance`] - If `value` is greater than
    ///   the balance of the `from` account.
    ///
    /// # Events
    ///
    /// * [`erc1155::TransferSingle`] - If the arrays contain one element.
    /// * [`erc1155::TransferBatch`] - If the arrays contain more than one
    ///   element.
    ///
    /// # Panics
    ///
    /// * If updated balance and/or supply exceeds [`U256::MAX`], may happen
    ///   during the `mint` operation.
    fn _update(
        &mut self,
        from: Address,
        to: Address,
        token_ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), erc1155::Error> {
        self.erc1155._update(from, to, token_ids.clone(), values.clone())?;

        if from.is_zero() {
            for (&token_id, &value) in token_ids.iter().zip(values.iter()) {
                self.total_supply
                    .setter(token_id)
                    .update_check_add(value)
                    .expect("should not exceed U256::MAX for total_supply");
            }

            let total_mint_value = values.iter().sum();
            self.total_supply_all
                .update_check_add(total_mint_value)
                .expect("should not exceed U256::MAX for total_supply_all");
        }

//! Optional Burnable extension of the ERC-1155 standard.

use alloc::vec::Vec;

use alloy_primitives::{Address, U256};
use openzeppelin_stylus_proc::interface_id;
use stylus_sdk::prelude::*;

use crate::token::erc1155::{
    self, ERC1155MissingApprovalForAll, Erc1155, IErc1155,
};

/// Extension of [`Erc1155`] that allows token holders to destroy both their
/// own tokens and those that they have been approved to use.
#[interface_id]
#[public]
pub trait IErc1155Burnable {
    /// The error type associated to this trait implementation.
    type Error: Into<alloc::vec::Vec<u8>>;

    /// Destroys a `value` amount of token from `account`.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `account` - Account to burn tokens from.
    /// * `token_id` - Token id to be burnt.
    /// * `value` - Amount to be burnt.
    ///
    /// # Errors
    ///
    /// * [`erc1155::Error::MissingApprovalForAll`] - If the caller is not
    ///   `account` address and the `account` has not been approved.
    /// * [`erc1155::Error::InvalidSender`] - If `from` is the
    ///   [`Address::ZERO`].
    /// * [`erc1155::Error::InsufficientBalance`] - If `value` is greater than
    ///   the balance of the `from` account.
    fn burn(
        &mut self,
        account: Address,
        token_id: U256,
        value: U256,
    ) -> Result<(), Self::Error>;

    /// Destroys a batch of tokens from `account`.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the contract's state.
    /// * `account` - Accounts to burn tokens from.
    /// * `token_ids` - All token id to be burnt.
    /// * `values` - All amount to be burnt.
    ///
    /// # Errors
    ///
    /// * [`erc1155::Error::MissingApprovalForAll`] - If the caller is not
    ///   `account` address and the `account` has not been approved.
    /// * [`erc1155::Error::InvalidSender`] - If `from` is the
    ///   [`Address::ZERO`].
    /// * [`erc1155::Error::InvalidArrayLength`] - If length of `ids` is not
    ///   equal to length of `values`.
    /// * [`erc1155::Error::InsufficientBalance`] - If any of the `values` is
    ///   greater than the balance of the respective token from `tokens` of the
    ///   `from` account.
    fn burn_batch(
        &mut self,
        account: Address,
        token_ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), Self::Error>;
}

#[public]
impl IErc1155Burnable for Erc1155 {
    type Error = erc1155::Error;

    fn burn(
        &mut self,
        account: Address,
        token_id: U256,
        value: U256,
    ) -> Result<(), Self::Error> {
        self.ensure_approved_or_owner(account)?;
        self._burn(account, token_id, value)
    }

    fn burn_batch(
        &mut self,
        account: Address,
        token_ids: Vec<U256>,
        values: Vec<U256>,
    ) -> Result<(), Self::Error> {
        self.ensure_approved_or_owner(account)?;
        self._burn_batch(account, token_ids, values)
    }
}

impl Erc1155 {
    fn ensure_approved_or_owner(
        &self,
        account: Address,
    ) -> Result<(), erc1155::Error> {
        let sender = self.vm().msg_sender();
        if account != sender && !self.is_approved_for_all(account, sender) {
            return Err(erc1155::Error::MissingApprovalForAll(
                ERC1155MissingApprovalForAll {
                    owner: account,
                    operator: sender,
                },
            ));
        }
        Ok(())
    }
}

