        fn init(
            &mut self,
            receiver: Address,
            size: usize,
        ) -> (Vec<U256>, Vec<U256>) {
            let token_ids = random_token_ids(size);
            let values = random_values(size);

            self._mint_batch(
                receiver,
                token_ids.clone(),
                values.clone(),
                &vec![0, 1, 2, 3].into(),
