            let vm = TestVM::default();
            vm.set_sender(alice);
            let mut bit_map = BitMap::from(&vm);
            prop_assert!(!bit_map.get(value));
            bit_map.set(value);
            prop_assert!(bit_map.get(value));
        });
    }

    #[test]
    fn unset_value() {
        proptest!(|(value: U256, alice: Address)| {
            let vm = TestVM::default();
            vm.set_sender(alice);
            let mut bit_map = BitMap::from(&vm);
            bit_map.set(value);
            prop_assert!(bit_map.get(value));
            bit_map.unset(value);
            prop_assert!(!bit_map.get(value));
        });
    }

    #[test]
    fn set_to_value() {
        proptest!(|(value: U256, alice: Address)| {
            let vm = TestVM::default();
            vm.set_sender(alice);
            let mut bit_map = BitMap::from(&vm);
            bit_map.set_to(value, true);
            prop_assert!(bit_map.get(value));
            bit_map.set_to(value, false);
            prop_assert!(!bit_map.get(value));
        });
    }
