/// An error that occurred while calling the [`Trace`] checkpoint contract.
#[derive(SolidityError, Debug)]
pub enum Error {
    /// A value was attempted to be inserted into a past checkpoint.
    CheckpointUnorderedInsertion(CheckpointUnorderedInsertion),
}

impl MethodError for Error {
    fn encode(self) -> alloc::vec::Vec<u8> {
        self.into()
    }
}

/// State of a [`Trace`] contract.
#[storage]
pub struct Trace<S: Size> {
    /// Stores checkpoints in a dynamic array sorted by key.
    pub(crate) checkpoints: StorageVec<Checkpoint<S>>,
}

/// State of a [`Checkpoint`] contract.
#[storage]
pub struct Checkpoint<S: Size> {
    /// The key of the checkpoint. Used as a sorting key.
    pub(crate) key: S::KeyStorage,
    /// The value corresponding to the key.
    pub(crate) value: S::ValueStorage,
}

impl<S: Size> Trace<S> {
    /// Pushes a (`key`, `value`) pair into a `Trace` so that it is
    /// stored as the checkpoint.
    ///
    /// Returns the previous value and the new value as an ordered pair.
    ///
    /// IMPORTANT: Never accept `key` as user input, since an arbitrary
    /// `U96::MAX` key set will disable the library.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the checkpoint's state.
    /// * `key` - Latest checkpoint key to insert.
    /// * `value` - Checkpoint value corresponding to `key`.
    ///
    /// # Errors
    ///
    /// * [`Error::CheckpointUnorderedInsertion`] - If the `key` is lower than
    ///   previously pushed checkpoint's key (necessary to maintain sorted
    ///   order).
    pub fn push(
        &mut self,
        key: S::Key,
        value: S::Value,
    ) -> Result<(S::Value, S::Value), Error> {
        self._insert(key, value)
    }

    /// Returns the value in the first (oldest) checkpoint with key greater or
    /// equal than the search key, or `S::Value::ZERO` if there is none.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `key` - Checkpoint's key to lookup.
    pub fn lower_lookup(&self, key: S::Key) -> S::Value {
        let len = self.length();
        let pos = self._lower_binary_lookup(key, U256::ZERO, len);
        if pos == len {
            S::Value::ZERO
        } else {
            self._index(pos).value.get()
        }
    }

    /// Returns the value in the last (most recent) checkpoint with key
    /// lower or equal than the search key, or `S::Value::ZERO` if there is
    /// none.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `key` - Checkpoint's key to lookup.
    pub fn upper_lookup(&self, key: S::Key) -> S::Value {
        let len = self.length();
        let pos = self._upper_binary_lookup(key, U256::ZERO, len);
        if pos == U256::ZERO {
            S::Value::ZERO
        } else {
            self._index(pos - uint!(1_U256)).value.get()
        }
    }

    /// Returns the value in the last (most recent) checkpoint with key lower or
    /// equal than the search key, or `S::Value::ZERO` if there is none.
    ///
    /// This is a variant of [`Self::upper_lookup`] that is optimized to find
    /// "recent" checkpoints (checkpoints with high keys).
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `key` - Checkpoint's key to query.
    pub fn upper_lookup_recent(&self, key: S::Key) -> S::Value {
        let len = self.length();

        let mut low = U256::ZERO;
        let mut high = len;

        if len > uint!(5_U256) {
            let mid = len - len.sqrt();
            if key < self._index(mid).key.get() {
                high = mid;
            } else {
                low = mid + uint!(1_U256);
            }
        }

        let pos = self._upper_binary_lookup(key, low, high);

        if pos == U256::ZERO {
            S::Value::ZERO
        } else {
            self._index(pos - uint!(1_U256)).value.get()
        }
    }

    /// Returns the value in the most recent checkpoint, or `S::Value::ZERO` if
    /// there are no checkpoints.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    pub fn latest(&self) -> S::Value {
        let pos = self.length();
        if pos == U256::ZERO {
            S::Value::ZERO
        } else {
            self._index(pos - uint!(1_U256)).value.get()
        }
    }

    /// Returns whether there is a checkpoint in the structure (i.g. it is not
    /// empty), and if so, the key and value in the most recent checkpoint.
    /// Otherwise, [`None`] will be returned.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    pub fn latest_checkpoint(&self) -> Option<(S::Key, S::Value)> {
        let pos = self.length();
        if pos == U256::ZERO {
            None
        } else {
            let checkpoint = self._index(pos - uint!(1_U256));
            Some((checkpoint.key.get(), checkpoint.value.get()))
        }
    }

    /// Returns the number of checkpoints.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    pub fn length(&self) -> U256 {
        U256::from(self.checkpoints.len())
    }

    /// Returns checkpoint at given position.
    ///
    /// # Panics
    ///
    /// If `pos` exceeds [`Self::length`].
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `pos` - Index of the checkpoint.
    pub fn at(&self, pos: U32) -> (S::Key, S::Value) {
        let guard = self.checkpoints.get(pos).unwrap_or_else(|| {
            panic!("should get checkpoint at index `{pos}`")
        });
        (guard.key.get(), guard.value.get())
    }

    /// Pushes a (`key`, `value`) pair into an ordered list of checkpoints,
    /// either by inserting a new checkpoint, or by updating the last one.
    /// Returns the previous value and the new value as an ordered pair.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the checkpoint's state.
    /// * `key` - The key of the checkpoint to insert.
    /// * `value` - Checkpoint value corresponding to insertion `key`.
    ///
    /// # Errors
    ///
    /// * [`Error::CheckpointUnorderedInsertion`] - If the `key` is lower than
    ///   the previously inserted one.
    fn _insert(
        &mut self,
        key: S::Key,
        value: S::Value,
    ) -> Result<(S::Value, S::Value), Error> {
        let pos = self.length();
        if pos > U256::ZERO {
            let last = self._index(pos - uint!(1_U256));
            let last_key = last.key.get();
            let last_value = last.value.get();

            // Checkpoint keys must be non-decreasing.
            if last_key > key {
                return Err(CheckpointUnorderedInsertion {}.into());
            }

            // Update or push new checkpoint
            if last_key == key {
                self._index_mut(pos - uint!(1_U256)).value.set(value);
            } else {
                self._unchecked_push(key, value);
            }
            Ok((last_value, value))
        } else {
            self._unchecked_push(key, value);
            Ok((S::Value::ZERO, value))
        }
    }

    /// Return the index of the last (most recent) checkpoint with key lower or
    /// equal than the search key, or `high` if there is none.
    ///
    /// Indexes `low` and `high` define a section where to do the search, with
    /// inclusive `low` and exclusive `high`.
    ///
    /// WARNING: `high` should not be greater than the array's length.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `key` - Checkpoint key to lookup.
    /// * `low` - Inclusive index where search begins.
    /// * `high` - Exclusive index where search ends.
    fn _upper_binary_lookup(
        &self,
        key: S::Key,
        mut low: U256,
        mut high: U256,
    ) -> U256 {
        while low < high {
            let mid = low.average(high);
            if self._index(mid).key.get() > key {
                high = mid;
            } else {
                low = mid + uint!(1_U256);
            }
        }
        high
    }

    /// Return the index of the first (oldest) checkpoint with key is greater or
    /// equal than the search key, or `high` if there is none.
    ///
    /// Indexes `low` and `high` define a section where to do the search, with
    /// inclusive `low` and exclusive `high`.
    ///
    /// WARNING: `high` should not be greater than the array's length.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `key` - Checkpoint key to lookup.
    /// * `low` - Inclusive index where search begins.
    /// * `high` - Exclusive index where search ends.
    fn _lower_binary_lookup(
        &self,
        key: S::Key,
        mut low: U256,
        mut high: U256,
    ) -> U256 {
        while low < high {
            let mid = low.average(high);
            if self._index(mid).key.get() < key {
                low = mid + uint!(1_U256);
            } else {
                high = mid;
            }
        }
        high
    }

    /// Immutable access on an element of the checkpoint's array. The position
    /// is assumed to be within bounds.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the checkpoint's state.
    /// * `pos` - Index of the checkpoint.
    ///
    /// # Panics
    ///
    /// * If `pos` exceeds [`Self::length`].
    fn _index(&self, pos: U256) -> StorageGuard<'_, Checkpoint<S>> {
        self.checkpoints
            .get(pos)
            .unwrap_or_else(|| panic!("should get checkpoint at index `{pos}`"))
    }

    /// Mutable access on an element of the checkpoint's array. The position is
    /// assumed to be within bounds.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the checkpoint's state.
    /// * `pos` - Index of the checkpoint.
    ///
    /// # Panics
    ///
    /// * If `pos` exceeds [`Self::length`].
    fn _index_mut(&mut self, pos: U256) -> StorageGuardMut<'_, Checkpoint<S>> {
        self.checkpoints
            .setter(pos)
            .unwrap_or_else(|| panic!("should get checkpoint at index `{pos}`"))
    }
//! Smart contract for managing sets.

pub mod element;

/// Sets have the following properties:
///
/// * Elements are added, removed, and checked for existence in constant
///   time (O(1)).
/// * Elements are enumerated in O(n). No guarantees are made on the
///   ordering.
/// * Set can be cleared (all elements removed) in O(n).
use alloc::{vec, vec::Vec};

use alloy_primitives::U256;
pub use element::{Accessor, Element};
use stylus_sdk::{
    prelude::*,
    storage::{StorageMap, StorageType, StorageU256, StorageVec},
};

/// State of an [`EnumerableSet`] contract.
#[storage]
pub struct EnumerableSet<T: Element> {
    /// Values in the set.
    values: StorageVec<T::StorageElement>,
    /// Position is the index of the value in the `values` array plus 1.
    /// Position 0 is used to mean a value is not in the set.
    positions: StorageMap<T, StorageU256>,
}

impl<T: Element> EnumerableSet<T> {
    /// Adds a value to a set.
    ///
    /// Returns true if the `value` was added to the set, that is if it was not
    /// already present.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the set's state.
    /// * `value` - The value to add to the set.
    pub fn add(&mut self, value: T) -> bool {
        if self.contains(value) {
            false
        } else {
            self.values.push(value);

            let position = self.length();
            self.positions.setter(value).set(position);
            true
        }
    }

    /// Removes a `value` from a set.
    ///
    /// Returns true if the `value` was removed from the set, that is if it was
    /// present.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the set's state.
    /// * `value` - The value to remove from the set.
    #[allow(clippy::missing_panics_doc)]
    pub fn remove(&mut self, value: T) -> bool {
        let position = self.positions.get(value);

        if position.is_zero() {
            false
        } else {
            let value_index = position - U256::ONE;
            let last_index = self.length() - U256::ONE;

            if value_index != last_index {
                let last_value = self
                    .values
                    .get(last_index)
                    .expect("element at `last_index` must exist");

                self.values
                    .setter(value_index)
                    .expect(
                        "element at `value_index` must exist - is being removed",
                    )
                    .set(last_value);

                self.positions.setter(last_value).set(position);
            }

            self.values.pop();

            self.positions.delete(value);

            true
        }
    }

    /// Remove all values from a set.
    ///
    /// # WARNING
    ///
    /// This function has an unbounded cost that scales with set size.
    /// Developers should keep in mind that using it may render the function
    /// uncallable if the set grows to the point where clearing it consumes too
    /// much gas to fit in a block.
    ///
    /// # Arguments
    ///
    /// * `&mut self` - Write access to the set's state.
    #[allow(clippy::missing_panics_doc)]
    pub fn clear(&mut self) {
        for idx in 0..self.values.len() {
            let v = self
                .values
                .get(idx)
                .expect("element at index: {idx} must exist");
            self.positions.delete(v);
        }

        self.values.erase();
    }

    /// Returns true if the `value` is in the set.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the set's state.
    /// * `value` - The value to check for in the set.
    #[must_use]
    pub fn contains(&self, value: T) -> bool {
        !self.positions.get(value).is_zero()
    }

    /// Returns the number of values in the set.
    ///
    /// Note this implementation's maximum length will technically be `usize`
    /// because that is the type returned by the underlying
    /// [`StorageVec::len`].
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the set's state.
    #[must_use]
    pub fn length(&self) -> U256 {
        U256::from(self.values.len())
    }

    /// Returns the value stored at position `index` in the set.
    ///
    /// Note that there are no guarantees on the ordering of values inside the
    /// array, and it may change when more values are added or removed.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the set's state.
    /// * `index` - The index of the value to return.
    #[must_use]
    pub fn at(&self, index: U256) -> Option<T> {
        self.values.get(index)
    }

    /// Returns the entire set in an array.
    ///
    /// # WARNING
    ///
    /// This operation will copy the entire storage to memory, which can be
    /// quite expensive. This is designed to mostly be used by view
    /// accessors that are queried without any gas fees. Developers should keep
    /// in mind that this function has an unbounded cost, and using it as
    /// part of a state-changing function may render the function uncallable
    /// if the set grows to a point where copying to memory consumes too much
    /// gas to fit in a block.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the set's state.
    #[allow(clippy::missing_panics_doc)]
    #[must_use]
    pub fn values(&self) -> Vec<T> {
        let mut values = Vec::new();
        for idx in 0..self.values.len() {
            values.push(
                self.values
                    .get(idx)
                    .expect("element at index: {idx} must exist"),
            );
        }
        values
    }

    /// Returns a slice of the set in an array.
    ///
    /// This function allows querying subsets of large sets to avoid
    /// out-of-gas scenarios when the full set would be too expensive
    /// to return in a single call.
    ///
    /// # WARNING
    ///
    /// This operation will copy the entire storage to memory, which can be
    /// quite expensive. This is designed to mostly be used by view
    /// accessors that are queried without any gas fees. Developers should keep
    /// in mind that this function has an unbounded cost, and using it as
    /// part of a state-changing function may render the function uncallable
    /// if the set grows to a point where copying to memory consumes too much
    /// gas to fit in a block.
    ///
    /// # Arguments
    ///
    /// * `&self` - Read access to the set's state.
    /// * `start` - The starting index (inclusive).
    /// * `end` - The ending index (exclusive).
    #[allow(clippy::missing_panics_doc)]
    #[must_use]
    pub fn values_slice(&self, start: U256, end: U256) -> Vec<T> {
        let len = self.length();

        // clamp parameters to valid ranges as in Solidity implementation: <https://github.com/OpenZeppelin/openzeppelin-contracts/blob/448538259f1feeb24f3e3201115d70818ba876cb/contracts/utils/structs/EnumerableSet.sol#L189>.
        let end = core::cmp::min(end, len);
        let start = core::cmp::min(start, end);

        // Uses optimized native iteration for typical cases where indices
        // fit within [`usize`] bounds. Falls back to [`U256`] arithmetic for
        // extremely large indices (theoretical edge case).
        if let (Ok(start_idx), Ok(end_idx)) =
            (usize::try_from(start), usize::try_from(end))
        {
            // fast path: use native [`usize`] iteration with iterator
            // chains.
            (start_idx..end_idx)
                .map(|idx| {
                    self.at(U256::from(idx))
                        .expect("element at index: {idx} must exist")
                })
                .collect()
        } else {
            // slow path: pure [`U256`] arithmetic for extremely large indices.
            let mut result = Vec::new();
            let mut current = start;

            while current < end {
                let value = self
                    .at(current)
                    .expect("element at index: {current} must exist");
                result.push(value);

                current += U256::ONE;
            }

            result
        }
    }
}

