//! Helper for reading and writing primitive types to specific storage slots.
use alloy_primitives::U256;
use stylus_sdk::{host::VM, prelude::*};

const SLOT_BYTE_SPACE: u8 = 32;

/// Helper for reading and writing primitive types to specific storage slots.
///
/// Storage slots are often used to avoid storage conflict when dealing with
/// upgradeable contracts. This library helps with reading and writing to such
/// slots without the need for low-level operations.
///
/// The functions in this library return appropriate storage types that contain
/// a `value` member that can be used to read or write.
///
/// Example usage to set ERC-1967 implementation slot:
///
/// ```rust
/// extern crate alloc;
///
/// use alloc::{vec, vec::Vec};
/// use alloy_primitives::{b256, Address, B256};
/// use openzeppelin_stylus::utils::storage_slot::StorageSlot;
/// use stylus_sdk::{storage::StorageAddress, prelude::*};
///
/// const IMPLEMENTATION_SLOT: B256 = b256!("0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc");
///
/// #[storage]
/// #[entrypoint]
/// pub struct Erc1967;
///
/// #[public]
/// impl Erc1967 {
///     fn get_implementation(&self) -> Address {
///         return StorageSlot::get_slot::<StorageAddress>(self, IMPLEMENTATION_SLOT).get();
///     }
///
///     fn set_implementation(&mut self, new_implementation: Address) {
///         assert!(self.vm().code_size(new_implementation) > 0);
///         StorageSlot::get_slot::<StorageAddress>(self, IMPLEMENTATION_SLOT).set(new_implementation);
///     }
/// }
/// ```
pub struct StorageSlot;

impl StorageSlot {
    /// Returns a [`StorageType`] located at `slot`.
    ///
    /// # Arguments
    ///
    /// * `slot` - The slot to get the address from.
    #[must_use]
    pub fn get_slot<ST: StorageType>(
        context: &impl HostAccess<Host = VM>,
        slot: impl Into<U256>,
    ) -> ST {
        // SAFETY: Truncation is safe here because ST::SLOT_BYTES is never
        // larger than 32, so the subtraction cannot underflow and the
        // cast is always valid.
        #[allow(clippy::cast_possible_truncation)]
        unsafe {
            ST::new(
                slot.into(),
                SLOT_BYTE_SPACE - ST::SLOT_BYTES as u8,
                context.vm().clone(),
            )
        }
    }
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unused_self)]

    use alloy_primitives::{uint, Address, U256};
    use stylus_sdk::storage::StorageAddress;
    use stylus_sdk::testing::TestVM;

    use super::*;

    const IMPLEMENTATION_SLOT: U256 = uint!(12345_U256);

    #[storage]
    #[entrypoint]
    pub struct Erc1967 {
        address: StorageAddress,
    }

    #[public]
    impl Erc1967 {
        fn get_implementation(&self) -> Address {
            StorageSlot::get_slot::<StorageAddress>(self, IMPLEMENTATION_SLOT)
                .get()
        }

        fn set_implementation(&self, new_implementation: Address) {
            StorageSlot::get_slot::<StorageAddress>(self, IMPLEMENTATION_SLOT)
                .set(new_implementation);
        }

        fn get_address(&self) -> Address {
            self.address.get()
        }

        fn set_address(&mut self, new_address: Address) {
            self.address.set(new_address);
        }

        fn get_address_at_zero_slot(&self) -> Address {
            StorageSlot::get_slot::<StorageAddress>(self, U256::ZERO).get()
        }

        fn set_address_at_zero_slot(&mut self, new_address: Address) {
            StorageSlot::get_slot::<StorageAddress>(self, U256::ZERO)
                .set(new_address);
        }
    }

    #[test]
    fn test_storage_slot() {
        let contract_vm = TestVM::default();
        let contract_address = Address::from([160u8; 20]);
        contract_vm.set_contract_address(contract_address);
        let mut contract = Erc1967::from(&contract_vm);
        let alice = Address::from([1u8; 20]);
        let impl_address = Address::from([2u8; 20]);

        let implementation = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_implementation();
        assert_eq!(implementation, Address::ZERO);

        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .set_implementation(impl_address);

        let implementation = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_implementation();
        assert_eq!(implementation, impl_address);
        let address = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_address_at_zero_slot();
        assert_eq!(address, Address::ZERO);
        let address = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_address();
        assert_eq!(address, Address::ZERO);

        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .set_address(impl_address);

        let implementation = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_implementation();
        assert_eq!(implementation, impl_address);
        let address = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_address_at_zero_slot();
        assert_eq!(address, impl_address);
        let address = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_address();
        assert_eq!(address, impl_address);

        ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .set_address_at_zero_slot(alice);

        let implementation = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_implementation();
        assert_eq!(implementation, impl_address);
        let address = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_address_at_zero_slot();
        assert_eq!(address, alice);
        let address = ({
            contract_vm.set_sender(alice);
            &mut contract
        })
        .get_address();
        assert_eq!(address, alice);
    }
}
//! A collection of utilities for working with [`Address`].

use alloc::vec::Vec;

use alloy_primitives::Address;
pub use sol::*;
use stylus_sdk::{
    call::{self},
    prelude::Call,
    prelude::*,
    stylus_core::calls::errors::MethodError,
};

#[cfg_attr(coverage_nightly, coverage(off))]
mod sol {
    use alloy_sol_macro::sol;

    sol! {
        /// There's no code at `target` (it is not a contract).
        ///
        /// * `target` - Address of the target contract.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error AddressEmptyCode(address target);

        /// A call to an address target failed. The target may have reverted
        /// without a revert reason.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error FailedCall();

        /// A call to an address target failed. The target may have reverted
        /// with a reason.
        ///
        /// * `reason` - The revert reason that was returned by the call.
        #[derive(Debug)]
        #[allow(missing_docs)]
        error FailedCallWithReason(bytes reason);
    }
}

/// An [`AddressUtils`] error.
#[derive(SolidityError, Debug)]
pub enum Error {
    /// There's no code at `target` (it is not a contract).
    EmptyCode(AddressEmptyCode),
    /// A call to an address target failed. The target may have reverted
    /// without a revert reason.
    FailedCall(FailedCall),
    /// A call to an address target failed. The target may have reverted
    /// with a reason.
    FailedCallWithReason(FailedCallWithReason),
}

impl MethodError for Error {
    fn encode(self) -> alloc::vec::Vec<u8> {
        self.into()
    }
}

/// A collection of utilities for working with [`Address`].
pub struct AddressUtils;

impl AddressUtils {
    /// Performs a delegate call to `target` with the given `data`.
    ///
    /// # Arguments
    ///
    /// * `context` - Mutable access to the contract's state.
    /// * `target` - The address of the target contract.
    /// * `data` - The data to pass to the target contract.
    ///
    /// # Errors
    ///
    /// * [`Error::FailedCall`] - If the call to the target contract fails
    ///   without a revert reason.
    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
    ///   fails with a revert reason or if the call fails for any other reason.
    /// * [`Error::EmptyCode`] - If the target contract has no code.
    pub fn function_delegate_call<T: TopLevelStorage + HostAccess>(
        context: &mut T,
        target: Address,
        data: &[u8],
    ) -> Result<Vec<u8>, Error> {
        let call = Call::new_mutating(context);
        let result =
            unsafe { call::delegate_call(context.vm(), call, target, data) };
        Self::verify_call_result_from_target(context, target, result)
    }

    // TODO: Support more result types out of the box (e.g. `U256`, `U160`,
    // `String`, etc.).
    /// Helper function to verify that a low level call to smart-contract was
    /// successful.
    ///
    /// Reverts if the target was not a contract or if the call fails for any
    /// other reason. Bubbles up the revert reason (falling back to
    /// [`Error::FailedCall`]) in case of an unsuccessful call.
    ///
    /// # Arguments
    ///
    /// * `target` - The address of the target contract.
    /// * `result` - The result of the call.
    ///
    /// # Errors
    ///
    /// * [`Error::EmptyCode`] - If the target contract has no code.
    /// * [`Error::FailedCallWithReason`] - If the call to the target contract
    ///   fails with a revert reason or if the call fails for any other reason.
    /// * [`Error::FailedCall`] - If the call to the target contract fails
    ///   without a revert reason.
    pub fn verify_call_result_from_target<C: HostAccess, T: AsRef<[u8]>>(
        context: &C,
        target: Address,
        result: Result<T, stylus_sdk::stylus_core::calls::errors::Error>,
    ) -> Result<T, Error> {
        match result {
            Ok(returndata) => {
                if returndata.as_ref().is_empty()
                    && context.vm().code_size(target) == 0
                {
                    return Err(AddressEmptyCode { target }.into());
                }
                Ok(returndata)
            }
            Err(e) => Err(Self::revert(e)),
        }
    }
}

impl AddressUtils {
    /// Reverts with `error` if revert reason exists. Otherwise reverts with
    /// [`Error::FailedCall`].
    ///
    /// This behavior is aligned with Solidity implementation of
    /// [Address.sol].
    ///
    /// [Address.sol]: https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/contracts/utils/Address.sol
    fn revert(error: stylus_sdk::stylus_core::calls::errors::Error) -> Error {
        match &error {
            stylus_sdk::stylus_core::calls::errors::Error::Revert(data)
                if data.is_empty() =>
            {
                FailedCall {}.into()
            }
            _ => FailedCallWithReason { reason: error.encode().into() }.into(),
        }
    }
}
