 57	/// A sentinel storage slot used by the implementation to distinguish
 58	/// implementation vs. proxy ([`delegate_call`][delegate_call]) execution
 59	/// contexts.
 60	///
 61	/// The slot key is derived from `keccak256("Stylus.uups.logic.flag") - 1`,
 62	/// chosen to avoid storage collisions with application state.
 63	///
 64	/// Behavior:
 65	/// - When called directly on the implementation, `logic_flag == true`.
 66	/// - When called via a proxy ([`delegate_call`][delegate_call]), `logic_flag ==
 67	///   false` (i.e., the proxy’s storage does not contain this
 68	///   implementation-only flag).
 69	///
 70	/// Security notes:
 71	/// - This boolean flag replaces Solidity’s `immutable __self` pattern.
 72	///
 73	/// [delegate_call]: stylus_sdk::call::delegate_call
 74	pub const LOGIC_FLAG_SLOT: B256 = {
 75	    const HASH: [u8; 32] = keccak_const::Keccak256::new()
 76	        .update(b"Stylus.uups.logic.flag")
 77	        .finalize();
 78	    let slot = U256::from_be_bytes(HASH)
 79	        .wrapping_sub(uint!(1_U256))
 80	        .to_be_bytes::<32>();
 81	
 82	    B256::new(slot)
 83	};
