   566	    /// Imitates a Stylus high-level call, relaxing the requirement on the
   567	    /// return value: if data is returned, it must not be `false`, otherwise
   568	    /// calls are assumed to be successful.
   569	    ///
   570	    /// # Arguments
   571	    ///
   572	    /// * `token` - Address of the ERC-20 token contract.
   573	    /// * `call` - [`IErc20`] call that implements [`SolCall`] trait.
   574	    ///
   575	    /// # Errors
   576	    ///
   577	    /// * [`Error::SafeErc20FailedOperation`] - If `token` has no code, the call
   578	    ///   fails, or it returns a value other than `true`.
   579	    fn call_optional_return<T: HostAccess>(
   580	        context: &T,
   581	        token: Address,
   582	        call: &impl SolCall,
   583	    ) -> Result<(), Error> {
   584	        if context.vm().code_size(token) == 0 {
   585	            return Err(Error::SafeErc20FailedOperation(
   586	                SafeErc20FailedOperation { token },
   587	            ));
   588	        }
   589	
   590	        let result = unsafe {
   591	            RawCall::new(context.vm())
   592	                .clear_storage_cache()
   593	                .limit_return_data(0, BOOL_TYPE_SIZE)
   594	                .call(token, &call.abi_encode())
   595	        };
   596	
   597	        match result {
   598	            Ok(data)
   599	                if data.is_empty()
   600	                    || Bool::abi_decode_validate(&data)
   601	                        .is_ok_and(|success| success) =>
   602	            {
   603	                Ok(())
   604	            }
   605	            _ => Err(SafeErc20FailedOperation { token }.into()),
   606	        }
   607	    }
