101	/// Marks a UUPS proxy as initialized once, using a namespaced storage slot.
102	///
103	/// Call this from each implementation's initializer before assigning
104	/// ownership or other privileged state. The marker survives implementation
105	/// upgrades and does not add fields to the contract's storage layout. It is
106	/// intentionally separate from the UUPS version so an exposed version setter
107	/// cannot lock out the initializer.
108	///
109	/// # Errors
110	///
111	/// Returns [`Error::InvalidInitialization`] if the proxy was already marked.
112	pub fn initializer(
113	    context: &mut impl HostAccess<Host = stylus_sdk::host::VM>,
114	) -> Result<(), Error> {
115	    let mut initialized =
116	        StorageSlot::get_slot::<StorageBool>(context, INITIALIZED_SLOT);
117	    if initialized.get() {
118	        return Err(Error::InvalidInitialization(InvalidInitialization {}));
119	    }
120	    initialized.set(true);
121	    Ok(())
122	}
