391	#[implements(IUUPSUpgradeable, IErc1822Proxiable)]
392	impl UUPSUpgradeable {
393	    /// Initializes implementation-only state used for context checks.
394	    ///
395	    /// Sets `logic_flag = true` in the implementation’s storage to indicate
396	    /// a direct (non-delegated) execution context.
397	    ///
398	    /// # Arguments
399	    ///
400	    /// * `&mut self` - Write access to the contract's state.
401	    #[constructor]
402	    pub fn constructor(&mut self) {
403	        self.logic_flag().set(true);
404	    }
