 62	impl<P: PoseidonParams<F>, F: PrimeField> Poseidon2<P, F> {
 63	    /// Create a new Poseidon sponge.
 64	    ///
 65	    /// # Panics
 66	    ///
 67	    /// Panics if `P::D` is not greater than one or is not coprime to the field
 68	    /// order, because then the S-box is not a permutation.
 69	    #[must_use]
 70	    #[inline]
 71	    pub fn new() -> Self {
 72	        assert!(
 73	            Self::sbox_exponent_is_permutation(),
 74	            "Poseidon S-box exponent must be greater than one and coprime to the field order"
 75	        );
 76	
 77	        Self {
 78	            phantom: core::marker::PhantomData,
 79	            state: vec![F::zero(); P::T].into_boxed_slice(),
 80	            mode: Mode::Absorbing,
 81	            // Begin index from `CAPACITY`. Skip capacity elements.
 82	            index: P::CAPACITY,
 83	        }
 84	    }
 85	
 86	    /// Check whether raising to `P::D` is a permutation of the field.
 87	    #[inline]
 88	    fn sbox_exponent_is_permutation() -> bool {
 89	        let degree = u16::from(P::D);
 90	        if degree <= 1 {
 91	            return false;
 92	        }
 93	
 94	        // x -> x^D is a permutation of F_p exactly when gcd(D, p - 1) = 1.
 95	        // Reduce p modulo D while iterating over its bits, avoiding conversion
 96	        // of the field modulus to a machine-sized integer.
 97	        let modulus_mod_degree =
 98	            F::MODULUS.bit_be_trimmed_iter().fold(0u16, |remainder, bit| {
 99	                (remainder * 2 + u16::from(bit)) % degree
100	            });
101	        let mut left = degree;
102	        let mut right = (modulus_mod_degree + degree - 1) % degree;
103	        while right != 0 {
104	            (left, right) = (right, left % right);
105	        }
106	        left == 1
107	    }
108	
109	    /// Size of poseidon sponge's state.
110	    #[must_use]
111	    pub const fn state_size() -> usize {
112	        P::T
113	    }
114	
115	    /// Start index of partial rounds.
116	    ///
117	    /// This represents the point where the algorithm transitions from full
118	    /// rounds to partial rounds in the Poseidon permutation.
119	    #[must_use]
120	    const fn partial_round_start() -> usize {
121	        P::ROUNDS_F / 2
122	    }
123	
124	    /// End index of partial rounds (noninclusive).
125	    ///
126	    /// This represents the point where the algorithm transitions from partial
127	    /// rounds back to full rounds in the Poseidon permutation.
128	    #[must_use]
129	    const fn partial_round_end() -> usize {
130	        Self::partial_round_start() + P::ROUNDS_P
131	    }
132	
133	    /// Total number of rounds.
134	    ///
135	    /// This is the sum of full rounds and partial rounds in the Poseidon
136	    /// permutation.
137	    #[must_use]
138	    const fn rounds() -> usize {
139	        P::ROUNDS_F + P::ROUNDS_P
140	    }
141	
142	    /// Absorb a single element into the sponge.
143	    ///
144	    /// Transitions from [`Mode::Absorbing`] to [`Mode::Squeezing`] mode are
145	    /// unidirectional.
146	    ///
147	    /// # Panics
148	    ///
149	    /// May panic if absorbing while squeezing.
150	    #[inline]
151	    pub fn absorb(&mut self, elem: &F) {
152	        if let Mode::Squeezing = self.mode {
153	            panic!("cannot absorb while squeezing");
154	        }
155	
156	        if self.index == Self::state_size() {
157	            self.permute();
158	            self.index = P::CAPACITY;
159	        }
160	
161	        self.state[self.index] += elem;
162	        self.index += 1;
163	    }
164	
165	    /// Absorb batch of elements into the sponge.
166	    #[inline]
167	    pub fn absorb_batch(&mut self, elems: &[F]) {
168	        for elem in elems {
169	            self.absorb(elem);
170	        }
171	    }
172	
173	    /// Permute elements in the sponge.
174	    #[inline]
175	    pub fn permute(&mut self) {
176	        // Linear layer at the beginning.
177	        self.matmul_external();
178	
179	        // Run the first half of the full round.
180	        for round in 0..Self::partial_round_start() {
181	            self.external_round(round);
182	        }
183	
184	        // Run the partial round.
185	        for round in Self::partial_round_start()..Self::partial_round_end() {
186	            self.internal_round(round);
187	        }
188	
189	        // Run the second half of the full round.
190	        for round in Self::partial_round_end()..Self::rounds() {
191	            self.external_round(round);
192	        }
193	    }
194	
195	    /// Apply external round to the state.
196	    ///
197	    /// External rounds apply S-box to all elements of the state vector,
198	    /// followed by the MDS matrix multiplication.
199	    #[inline]
200	    fn external_round(&mut self, round: usize) {
201	        self.add_rc_external(round);
202	        self.apply_sbox_external();
203	        self.matmul_external();
204	    }
205	
206	    /// Apply internal round to the state.
207	    ///
208	    /// Internal rounds apply S-box only to the first element of the state
209	    /// vector, followed by the MDS matrix multiplication, which is more
210	    /// efficient.
211	    #[inline]
212	    fn internal_round(&mut self, round: usize) {
213	        self.add_rc_internal(round);
214	        self.apply_sbox_internal();
215	        self.matmul_internal();
216	    }
217	
218	    /// Squeeze a single element from the sponge.
219	    ///
220	    /// When invoked from [`Mode::Absorbing`] mode, this function triggers a
221	    /// permutation and transitions to [`Mode::Squeezing`] mode.
222	    #[inline]
223	    pub fn squeeze(&mut self) -> F {
224	        if self.mode == Mode::Absorbing || self.index == Self::state_size() {
225	            self.permute();
226	            self.mode = Mode::Squeezing;
227	            self.index = P::CAPACITY;
228	        }
229	
230	        let elem = self.state[self.index];
231	        self.index += 1;
232	        elem
233	    }
234	
235	    /// Squeeze a batch of elements from the sponge.
236	    #[inline]
237	    pub fn squeeze_batch(&mut self, n: usize) -> Vec<F> {
238	        (0..n).map(|_| self.squeeze()).collect()
239	    }
240	
241	    /// Apply sbox to the entire state in the external round.
242	    ///
243	    /// This raises each element in the state to the power of D, which is
244	    /// the S-box degree defined in the Poseidon parameters.
245	    #[inline]
246	    fn apply_sbox_external(&mut self) {
247	        for elem in &mut self.state {
248	            *elem = elem.pow(P::D);
249	        }
250	    }
251	
252	    /// Apply sbox to the first element in the internal round.
253	    ///
254	    /// This applies the S-box (raising to power D) only to the first element of
255	    /// the state, which is more efficient than applying it to all elements.
256	    #[inline]
257	    fn apply_sbox_internal(&mut self) {
258	        self.state[0] = self.state[0].pow(P::D);
259	    }
