258	impl From<AffinePoint> for CompressedPointY {
259	    fn from(point: AffinePoint) -> Self {
260	        let mut s: [u8; 32] = point
261	            .y
262	            .into_bigint()
263	            .into_bytes_le()
264	            .try_into()
265	            .expect("Y coordinate should be 32 bytes");
266	
267	        // Using the last bit to encode `x`, since the base field modulus is
268	        // asserted to have a spare bit.
269	        let is_odd = point.x.into_bigint().is_odd();
270	        s[31] ^= u8::from(is_odd) << 7;
271	
272	        CompressedPointY(s)
273	    }
274	}
