276	/// Ed25519 signature representation.
277	///
278	/// Signature verification libraries are expected to reject invalid
279	/// field elements at the time a signature is verified.
280	#[derive(Copy, Clone, Eq, PartialEq)]
281	pub struct Signature {
282	    /// `R` is an `EdwardsPoint`, formed by using an hash function with
283	    /// `512-bits` output to produce the digest of:
284	    ///
285	    /// * the nonce half of the `ExpandedSecretKey`, and
286	    /// * the message to be signed.
287	    ///
288	    /// This digest is then interpreted as a `Scalar` and reduced into an
289	    /// element in ℤ/lℤ.  The scalar is then multiplied by the distinguished
290	    /// basepoint to produce `R`, and `EdwardsPoint`.
291	    pub R: ProjectivePoint,
292	
293	    /// `s` is a `Scalar`, formed by using a hash function with `512-bits`
294	    /// output to produce the digest of:
295	    ///
296	    /// * the `r` portion of this `Signature`,
297	    /// * the `PublicKey` which should be used to verify this `Signature`, and
298	    /// * the message to be signed.
299	    ///
300	    /// This digest is then interpreted as a `Scalar` and reduced into an
301	    /// element in ℤ/lℤ.
302	    pub s: Scalar,
303	}
304	
305	impl Signature {
306	    /// Converts the signature to a 64-byte array.
307	    ///
308	    /// The first 32 bytes contain the compressed encoding of the `R` value.
309	    /// The last 32 bytes contain the canonical encoding of the `s` scalar.
310	    #[must_use]
311	    pub fn to_bytes(&self) -> [u8; SIGNATURE_LENGTH] {
312	        let mut bytes = [0u8; 64];
313	
314	        // Get the compressed representation of R
315	        let r_compressed = CompressedPointY::from(self.R.into_affine());
316	        bytes[..32].copy_from_slice(r_compressed.as_ref());
317	
318	        // Get the little-endian byte representation of s
319	        let s_bytes = self.s.into_bigint().into_bytes_le();
320	        bytes[32..].copy_from_slice(&s_bytes[..32]);
321	
322	        bytes
323	    }
324	
325	    /// Construct a signature from affine point `R` and scalar `s`.
326	    #[must_use]
327	    pub fn from_affine_R_s(R: AffinePoint, s: Scalar) -> Self {
328	        Signature { R: R.into(), s }
329	    }
330	}
