206	    /// Apply internal round to the state.
207	    ///
208	    /// Internal rounds apply S-box only to the first element of the state
209	    /// vector, followed by the MDS matrix multiplication, which is more
210	    /// efficient.
211	    #[inline]
212	    fn internal_round(&mut self, round: usize) {
213	        self.add_rc_internal(round);
214	        self.apply_sbox_internal();
215	        self.matmul_internal();
