258	impl From<AffinePoint> for CompressedPointY {
259	    fn from(point: AffinePoint) -> Self {
260	        let mut s: [u8; 32] = point
261	            .y
262	            .into_bigint()
263	            .into_bytes_le()
264	            .try_into()
265	            .expect("Y coordinate should be 32 bytes");
